use split_decls_genesis :: ourprelude :: * ; #[doc (keyword = "as")] #[doc = " Cast between types, or rename an import."] #[doc = ""] #[doc = " `as` is most commonly used to turn primitive types into other primitive types, but it has other"] #[doc = " uses that include turning pointers into addresses, addresses into pointers, and pointers into"] #[doc = " other pointers."] #[doc = ""] #[doc = " ```rust"] #[doc = " let thing1: u8 = 89.0 as u8;"] #[doc = " assert_eq!('B' as u32, 66);"] #[doc = " assert_eq!(thing1 as char, 'Y');"] #[doc = " let thing2: f32 = thing1 as f32 + 10.5;"] #[doc = " assert_eq!(true as u8 + thing2 as u8, 100);"] #[doc = " ```"] #[doc = ""] #[doc = " In general, any cast that can be performed via ascribing the type can also be done using `as`,"] #[doc = " so instead of writing `let x: u32 = 123`, you can write `let x = 123 as u32` (note: `let x: u32"] #[doc = " = 123` would be best in that situation). The same is not true in the other direction, however;"] #[doc = " explicitly using `as` allows a few more coercions that aren't allowed implicitly, such as"] #[doc = " changing the type of a raw pointer or turning closures into raw pointers."] #[doc = ""] #[doc = " `as` can be seen as the primitive for `From` and `Into`: `as` only works  with primitives"] #[doc = " (`u8`, `bool`, `str`, pointers, ...) whereas `From` and `Into`  also works with types like"] #[doc = " `String` or `Vec`."] #[doc = ""] #[doc = " `as` can also be used with the `_` placeholder when the destination type can be inferred. Note"] #[doc = " that this can cause inference breakage and usually such code should use an explicit type for"] #[doc = " both clarity and stability. This is most useful when converting pointers using `as *const _` or"] #[doc = " `as *mut _` though the [`cast`][const-cast] method is recommended over `as *const _` and it is"] #[doc = " [the same][mut-cast] for `as *mut _`: those methods make the intent clearer."] #[doc = ""] #[doc = " `as` is also used to rename imports in [`use`] and [`extern crate`][`crate`] statements:"] #[doc = ""] #[doc = " ```"] #[doc = " # #[allow(unused_imports)]"] #[doc = " use std::{mem as memory, net as network};"] #[doc = " // Now you can use the names `memory` and `network` to refer to `std::mem` and `std::net`."] #[doc = " ```"] #[doc = " For more information on what `as` is capable of, see the [Reference]."] #[doc = ""] #[doc = " [Reference]: ../reference/expressions/operator-expr.html#type-cast-expressions"] #[doc = " [`crate`]: keyword.crate.html"] #[doc = " [`use`]: keyword.use.html"] #[doc = " [const-cast]: pointer::cast"] #[doc = " [mut-cast]: primitive.pointer.html#method.cast-1"] mod as_keyword { } #[doc (keyword = "break")] #[doc = " Exit early from a loop or labelled block."] #[doc = ""] #[doc = " When `break` is encountered, execution of the associated loop body is"] #[doc = " immediately terminated."] #[doc = ""] #[doc = " ```rust"] #[doc = " let mut last = 0;"] #[doc = ""] #[doc = " for x in 1..100 {"] #[doc = "     if x > 12 {"] #[doc = "         break;"] #[doc = "     }"] #[doc = "     last = x;"] #[doc = " }"] #[doc = ""] #[doc = " assert_eq!(last, 12);"] #[doc = " println!(\"{last}\");"] #[doc = " ```"] #[doc = ""] #[doc = " A break expression is normally associated with the innermost loop enclosing the"] #[doc = " `break` but a label can be used to specify which enclosing loop is affected."] #[doc = ""] #[doc = " ```rust"] #[doc = " 'outer: for i in 1..=5 {"] #[doc = "     println!(\"outer iteration (i): {i}\");"] #[doc = ""] #[doc = "     '_inner: for j in 1..=200 {"] #[doc = "         println!(\"    inner iteration (j): {j}\");"] #[doc = "         if j >= 3 {"] #[doc = "             // breaks from inner loop, lets outer loop continue."] #[doc = "             break;"] #[doc = "         }"] #[doc = "         if i >= 2 {"] #[doc = "             // breaks from outer loop, and directly to \"Bye\"."] #[doc = "             break 'outer;"] #[doc = "         }"] #[doc = "     }"] #[doc = " }"] #[doc = " println!(\"Bye.\");"] #[doc = " ```"] #[doc = ""] #[doc = " When associated with `loop`, a break expression may be used to return a value from that loop."] #[doc = " This is only valid with `loop` and not with any other type of loop."] #[doc = " If no value is specified for `break;` it returns `()`."] #[doc = " Every `break` within a loop must return the same type."] #[doc = ""] #[doc = " ```rust"] #[doc = " let (mut a, mut b) = (1, 1);"] #[doc = " let result = loop {"] #[doc = "     if b > 10 {"] #[doc = "         break b;"] #[doc = "     }"] #[doc = "     let c = a + b;"] #[doc = "     a = b;"] #[doc = "     b = c;"] #[doc = " };"] #[doc = " // first number in Fibonacci sequence over 10:"] #[doc = " assert_eq!(result, 13);"] #[doc = " println!(\"{result}\");"] #[doc = " ```"] #[doc = ""] #[doc = " It is also possible to exit from any *labelled* block returning the value early."] #[doc = " If no value is specified for `break;` it returns `()`."] #[doc = ""] #[doc = " ```rust"] #[doc = " let inputs = vec![\"Cow\", \"Cat\", \"Dog\", \"Snake\", \"Cod\"];"] #[doc = ""] #[doc = " let mut results = vec![];"] #[doc = " for input in inputs {"] #[doc = "     let result = 'filter: {"] #[doc = "         if input.len() > 3 {"] #[doc = "             break 'filter Err(\"Too long\");"] #[doc = "         };"] #[doc = ""] #[doc = "         if !input.contains(\"C\") {"] #[doc = "             break 'filter Err(\"No Cs\");"] #[doc = "         };"] #[doc = ""] #[doc = "         Ok(input.to_uppercase())"] #[doc = "     };"] #[doc = ""] #[doc = "     results.push(result);"] #[doc = " }"] #[doc = ""] #[doc = " // [Ok(\"COW\"), Ok(\"CAT\"), Err(\"No Cs\"), Err(\"Too long\"), Ok(\"COD\")]"] #[doc = " println!(\"{:?}\", results)"] #[doc = " ```"] #[doc = ""] #[doc = " For more details consult the [Reference on \"break expression\"] and the [Reference on \"break and"] #[doc = " loop values\"]."] #[doc = ""] #[doc = " [Reference on \"break expression\"]: ../reference/expressions/loop-expr.html#break-expressions"] #[doc = " [Reference on \"break and loop values\"]:"] #[doc = " ../reference/expressions/loop-expr.html#break-and-loop-values"] mod break_keyword { } #[doc (keyword = "const")] #[doc = " Compile-time constants, compile-time blocks, compile-time evaluable functions, and raw pointers."] #[doc = ""] #[doc = " ## Compile-time constants"] #[doc = ""] #[doc = " Sometimes a certain value is used many times throughout a program, and it can become"] #[doc = " inconvenient to copy it over and over. What's more, it's not always possible or desirable to"] #[doc = " make it a variable that gets carried around to each function that needs it. In these cases, the"] #[doc = " `const` keyword provides a convenient alternative to code duplication:"] #[doc = ""] #[doc = " ```rust"] #[doc = " const THING: u32 = 0xABAD1DEA;"] #[doc = ""] #[doc = " let foo = 123 + THING;"] #[doc = " ```"] #[doc = ""] #[doc = " Constants must be explicitly typed; unlike with `let`, you can't ignore their type and let the"] #[doc = " compiler figure it out. Any constant value can be defined in a `const`, which in practice happens"] #[doc = " to be most things that would be reasonable to have in a constant (barring `const fn`s). For"] #[doc = " example, you can't have a [`File`] as a `const`."] #[doc = ""] #[doc = " [`File`]: crate::fs::File"] #[doc = ""] #[doc = " The only lifetime allowed in a constant is `'static`, which is the lifetime that encompasses"] #[doc = " all others in a Rust program. For example, if you wanted to define a constant string, it would"] #[doc = " look like this:"] #[doc = ""] #[doc = " ```rust"] #[doc = " const WORDS: &'static str = \"hello rust!\";"] #[doc = " ```"] #[doc = ""] #[doc = " Thanks to static lifetime elision, you usually don't have to explicitly use `'static`:"] #[doc = ""] #[doc = " ```rust"] #[doc = " const WORDS: &str = \"hello convenience!\";"] #[doc = " ```"] #[doc = ""] #[doc = " `const` items look remarkably similar to `static` items, which introduces some confusion as"] #[doc = " to which one should be used at which times. To put it simply, constants are inlined wherever"] #[doc = " they're used, making using them identical to simply replacing the name of the `const` with its"] #[doc = " value. Static variables, on the other hand, point to a single location in memory, which all"] #[doc = " accesses share. This means that, unlike with constants, they can't have destructors, and act as"] #[doc = " a single value across the entire codebase."] #[doc = ""] #[doc = " Constants, like statics, should always be in `SCREAMING_SNAKE_CASE`."] #[doc = ""] #[doc = " For more detail on `const`, see the [Rust Book] or the [Reference]."] #[doc = ""] #[doc = " ## Compile-time blocks"] #[doc = ""] #[doc = " The `const` keyword can also be used to define a block of code that is evaluated at compile time."] #[doc = " This is useful for ensuring certain computations are completed before optimizations happen, as well as"] #[doc = " before runtime. For more details, see the [Reference][const-blocks]."] #[doc = ""] #[doc = " ## Compile-time evaluable functions"] #[doc = ""] #[doc = " The other main use of the `const` keyword is in `const fn`. This marks a function as being"] #[doc = " callable in the body of a `const` or `static` item and in array initializers (commonly called"] #[doc = " \"const contexts\"). `const fn` are restricted in the set of operations they can perform, to"] #[doc = " ensure that they can be evaluated at compile-time. See the [Reference][const-eval] for more"] #[doc = " detail."] #[doc = ""] #[doc = " Turning a `fn` into a `const fn` has no effect on run-time uses of that function."] #[doc = ""] #[doc = " ## Other uses of `const`"] #[doc = ""] #[doc = " The `const` keyword is also used in raw pointers in combination with `mut`, as seen in `*const"] #[doc = " T` and `*mut T`. More about `const` as used in raw pointers can be read at the Rust docs for the [pointer primitive]."] #[doc = ""] #[doc = " [pointer primitive]: pointer"] #[doc = " [Rust Book]: ../book/ch03-01-variables-and-mutability.html#constants"] #[doc = " [Reference]: ../reference/items/constant-items.html"] #[doc = " [const-blocks]: ../reference/expressions/block-expr.html#const-blocks"] #[doc = " [const-eval]: ../reference/const_eval.html"] mod const_keyword { } #[doc (keyword = "continue")] #[doc = " Skip to the next iteration of a loop."] #[doc = ""] #[doc = " When `continue` is encountered, the current iteration is terminated, returning control to the"] #[doc = " loop head, typically continuing with the next iteration."] #[doc = ""] #[doc = " ```rust"] #[doc = " // Printing odd numbers by skipping even ones"] #[doc = " for number in 1..=10 {"] #[doc = "     if number % 2 == 0 {"] #[doc = "         continue;"] #[doc = "     }"] #[doc = "     println!(\"{number}\");"] #[doc = " }"] #[doc = " ```"] #[doc = ""] #[doc = " Like `break`, `continue` is normally associated with the innermost enclosing loop, but labels"] #[doc = " may be used to specify the affected loop."] #[doc = ""] #[doc = " ```rust"] #[doc = " // Print Odd numbers under 30 with unit <= 5"] #[doc = " 'tens: for ten in 0..3 {"] #[doc = "     '_units: for unit in 0..=9 {"] #[doc = "         if unit % 2 == 0 {"] #[doc = "             continue;"] #[doc = "         }"] #[doc = "         if unit > 5 {"] #[doc = "             continue 'tens;"] #[doc = "         }"] #[doc = "         println!(\"{}\", ten * 10 + unit);"] #[doc = "     }"] #[doc = " }"] #[doc = " ```"] #[doc = ""] #[doc = " See [continue expressions] from the reference for more details."] #[doc = ""] #[doc = " [continue expressions]: ../reference/expressions/loop-expr.html#continue-expressions"] mod continue_keyword { } #[doc (keyword = "crate")] #[doc = " A Rust binary or library."] #[doc = ""] #[doc = " The primary use of the `crate` keyword is as a part of `extern crate` declarations, which are"] #[doc = " used to specify a dependency on a crate external to the one it's declared in. Crates are the"] #[doc = " fundamental compilation unit of Rust code, and can be seen as libraries or projects. More can"] #[doc = " be read about crates in the [Reference]."] #[doc = ""] #[doc = " ```rust ignore"] #[doc = " extern crate rand;"] #[doc = " extern crate my_crate as thing;"] #[doc = " extern crate std; // implicitly added to the root of every Rust project"] #[doc = " ```"] #[doc = ""] #[doc = " The `as` keyword can be used to change what the crate is referred to as in your project. If a"] #[doc = " crate name includes a dash, it is implicitly imported with the dashes replaced by underscores."] #[doc = ""] #[doc = " `crate` can also be used as in conjunction with `pub` to signify that the item it's attached to"] #[doc = " is public only to other members of the same crate it's in."] #[doc = ""] #[doc = " ```rust"] #[doc = " # #[allow(unused_imports)]"] #[doc = " pub(crate) use std::io::Error as IoError;"] #[doc = " pub(crate) enum CoolMarkerType { }"] #[doc = " pub struct PublicThing {"] #[doc = "     pub(crate) semi_secret_thing: bool,"] #[doc = " }"] #[doc = " ```"] #[doc = ""] #[doc = " `crate` is also used to represent the absolute path of a module, where `crate` refers to the"] #[doc = " root of the current crate. For instance, `crate::foo::bar` refers to the name `bar` inside the"] #[doc = " module `foo`, from anywhere else in the same crate."] #[doc = ""] #[doc = " [Reference]: ../reference/items/extern-crates.html"] mod crate_keyword { } #[doc (keyword = "else")] #[doc = " What expression to evaluate when an [`if`] condition evaluates to [`false`]."] #[doc = ""] #[doc = " `else` expressions are optional. When no else expressions are supplied it is assumed to evaluate"] #[doc = " to the unit type `()`."] #[doc = ""] #[doc = " The type that the `else` blocks evaluate to must be compatible with the type that the `if` block"] #[doc = " evaluates to."] #[doc = ""] #[doc = " As can be seen below, `else` must be followed by either: `if`, `if let`, or a block `{}` and it"] #[doc = " will return the value of that expression."] #[doc = ""] #[doc = " ```rust"] #[doc = " let result = if true == false {"] #[doc = "     \"oh no\""] #[doc = " } else if \"something\" == \"other thing\" {"] #[doc = "     \"oh dear\""] #[doc = " } else if let Some(200) = \"blarg\".parse::<i32>().ok() {"] #[doc = "     \"uh oh\""] #[doc = " } else {"] #[doc = "     println!(\"Sneaky side effect.\");"] #[doc = "     \"phew, nothing's broken\""] #[doc = " };"] #[doc = " ```"] #[doc = ""] #[doc = " Here's another example but here we do not try and return an expression:"] #[doc = ""] #[doc = " ```rust"] #[doc = " if true == false {"] #[doc = "     println!(\"oh no\");"] #[doc = " } else if \"something\" == \"other thing\" {"] #[doc = "     println!(\"oh dear\");"] #[doc = " } else if let Some(200) = \"blarg\".parse::<i32>().ok() {"] #[doc = "     println!(\"uh oh\");"] #[doc = " } else {"] #[doc = "     println!(\"phew, nothing's broken\");"] #[doc = " }"] #[doc = " ```"] #[doc = ""] #[doc = " The above is _still_ an expression but it will always evaluate to `()`."] #[doc = ""] #[doc = " There is possibly no limit to the number of `else` blocks that could follow an `if` expression"] #[doc = " however if you have several then a [`match`] expression might be preferable."] #[doc = ""] #[doc = " Read more about control flow in the [Rust Book]."] #[doc = ""] #[doc = " [Rust Book]: ../book/ch03-05-control-flow.html#handling-multiple-conditions-with-else-if"] #[doc = " [`match`]: keyword.match.html"] #[doc = " [`false`]: keyword.false.html"] #[doc = " [`if`]: keyword.if.html"] mod else_keyword { } #[doc (keyword = "enum")] #[doc = " A type that can be any one of several variants."] #[doc = ""] #[doc = " Enums in Rust are similar to those of other compiled languages like C, but have important"] #[doc = " differences that make them considerably more powerful. What Rust calls enums are more commonly"] #[doc = " known as [Algebraic Data Types][ADT] if you're coming from a functional programming background."] #[doc = " The important detail is that each enum variant can have data to go along with it."] #[doc = ""] #[doc = " ```rust"] #[doc = " # struct Coord;"] #[doc = " enum SimpleEnum {"] #[doc = "     FirstVariant,"] #[doc = "     SecondVariant,"] #[doc = "     ThirdVariant,"] #[doc = " }"] #[doc = ""] #[doc = " enum Location {"] #[doc = "     Unknown,"] #[doc = "     Anonymous,"] #[doc = "     Known(Coord),"] #[doc = " }"] #[doc = ""] #[doc = " enum ComplexEnum {"] #[doc = "     Nothing,"] #[doc = "     Something(u32),"] #[doc = "     LotsOfThings {"] #[doc = "         usual_struct_stuff: bool,"] #[doc = "         blah: String,"] #[doc = "     }"] #[doc = " }"] #[doc = ""] #[doc = " enum EmptyEnum { }"] #[doc = " ```"] #[doc = ""] #[doc = " The first enum shown is the usual kind of enum you'd find in a C-style language. The second"] #[doc = " shows off a hypothetical example of something storing location data, with `Coord` being any"] #[doc = " other type that's needed, for example a struct. The third example demonstrates the kind of"] #[doc = " data a variant can store, ranging from nothing, to a tuple, to an anonymous struct."] #[doc = ""] #[doc = " Instantiating enum variants involves explicitly using the enum's name as its namespace,"] #[doc = " followed by one of its variants. `SimpleEnum::SecondVariant` would be an example from above."] #[doc = " When data follows along with a variant, such as with rust's built-in [`Option`] type, the data"] #[doc = " is added as the type describes, for example `Option::Some(123)`. The same follows with"] #[doc = " struct-like variants, with things looking like `ComplexEnum::LotsOfThings { usual_struct_stuff:"] #[doc = " true, blah: \"hello!\".to_string(), }`. Empty Enums are similar to [`!`] in that they cannot be"] #[doc = " instantiated at all, and are used mainly to mess with the type system in interesting ways."] #[doc = ""] #[doc = " For more information, take a look at the [Rust Book] or the [Reference]"] #[doc = ""] #[doc = " [ADT]: https://en.wikipedia.org/wiki/Algebraic_data_type"] #[doc = " [Rust Book]: ../book/ch06-01-defining-an-enum.html"] #[doc = " [Reference]: ../reference/items/enumerations.html"] mod enum_keyword { } #[doc (keyword = "extern")] #[doc = " Link to or import external code."] #[doc = ""] #[doc = " The `extern` keyword is used in two places in Rust. One is in conjunction with the [`crate`]"] #[doc = " keyword to make your Rust code aware of other Rust crates in your project, i.e., `extern crate"] #[doc = " lazy_static;`. The other use is in foreign function interfaces (FFI)."] #[doc = ""] #[doc = " `extern` is used in two different contexts within FFI. The first is in the form of external"] #[doc = " blocks, for declaring function interfaces that Rust code can call foreign code by. This use"] #[doc = " of `extern` is unsafe, since we are asserting to the compiler that all function declarations"] #[doc = " are correct. If they are not, using these items may lead to undefined behavior."] #[doc = ""] #[doc = " ```rust ignore"] #[doc = " // SAFETY: The function declarations given below are in"] #[doc = " // line with the header files of `my_c_library`."] #[doc = " #[link(name = \"my_c_library\")]"] #[doc = " unsafe extern \"C\" {"] #[doc = "     fn my_c_function(x: i32) -> bool;"] #[doc = " }"] #[doc = " ```"] #[doc = ""] #[doc = " This code would attempt to link with `libmy_c_library.so` on unix-like systems and"] #[doc = " `my_c_library.dll` on Windows at runtime, and panic if it can't find something to link to. Rust"] #[doc = " code could then use `my_c_function` as if it were any other unsafe Rust function. Working with"] #[doc = " non-Rust languages and FFI is inherently unsafe, so wrappers are usually built around C APIs."] #[doc = ""] #[doc = " The mirror use case of FFI is also done via the `extern` keyword:"] #[doc = ""] #[doc = " ```rust"] #[doc = " #[unsafe(no_mangle)]"] #[doc = " pub extern \"C\" fn callable_from_c(x: i32) -> bool {"] #[doc = "     x % 3 == 0"] #[doc = " }"] #[doc = " ```"] #[doc = ""] #[doc = " If compiled as a dylib, the resulting .so could then be linked to from a C library, and the"] #[doc = " function could be used as if it was from any other library."] #[doc = ""] #[doc = " For more information on FFI, check the [Rust book] or the [Reference]."] #[doc = ""] #[doc = " [Rust book]:"] #[doc = " ../book/ch19-01-unsafe-rust.html#using-extern-functions-to-call-external-code"] #[doc = " [Reference]: ../reference/items/external-blocks.html"] #[doc = " [`crate`]: keyword.crate.html"] mod extern_keyword { } #[doc (keyword = "false")] #[doc = " A value of type [`bool`] representing logical **false**."] #[doc = ""] #[doc = " `false` is the logical opposite of [`true`]."] #[doc = ""] #[doc = " See the documentation for [`true`] for more information."] #[doc = ""] #[doc = " [`true`]: keyword.true.html"] mod false_keyword { } #[doc (keyword = "fn")] #[doc = " A function or function pointer."] #[doc = ""] #[doc = " Functions are the primary way code is executed within Rust. Function blocks, usually just"] #[doc = " called functions, can be defined in a variety of different places and be assigned many"] #[doc = " different attributes and modifiers."] #[doc = ""] #[doc = " Standalone functions that just sit within a module not attached to anything else are common,"] #[doc = " but most functions will end up being inside [`impl`] blocks, either on another type itself, or"] #[doc = " as a trait impl for that type."] #[doc = ""] #[doc = " ```rust"] #[doc = " fn standalone_function() {"] #[doc = "     // code"] #[doc = " }"] #[doc = ""] #[doc = " pub fn public_thing(argument: bool) -> String {"] #[doc = "     // code"] #[doc = "     # \"\".to_string()"] #[doc = " }"] #[doc = ""] #[doc = " struct Thing {"] #[doc = "     foo: i32,"] #[doc = " }"] #[doc = ""] #[doc = " impl Thing {"] #[doc = "     pub fn new() -> Self {"] #[doc = "         Self {"] #[doc = "             foo: 42,"] #[doc = "         }"] #[doc = "     }"] #[doc = " }"] #[doc = " ```"] #[doc = ""] #[doc = " In addition to presenting fixed types in the form of `fn name(arg: type, ..) -> return_type`,"] #[doc = " functions can also declare a list of type parameters along with trait bounds that they fall"] #[doc = " into."] #[doc = ""] #[doc = " ```rust"] #[doc = " fn generic_function<T: Clone>(x: T) -> (T, T, T) {"] #[doc = "     (x.clone(), x.clone(), x.clone())"] #[doc = " }"] #[doc = ""] #[doc = " fn generic_where<T>(x: T) -> T"] #[doc = "     where T: std::ops::Add<Output = T> + Copy"] #[doc = " {"] #[doc = "     x + x + x"] #[doc = " }"] #[doc = " ```"] #[doc = ""] #[doc = " Declaring trait bounds in the angle brackets is functionally identical to using a `where`"] #[doc = " clause. It's up to the programmer to decide which works better in each situation, but `where`"] #[doc = " tends to be better when things get longer than one line."] #[doc = ""] #[doc = " Along with being made public via `pub`, `fn` can also have an [`extern`] added for use in"] #[doc = " FFI."] #[doc = ""] #[doc = " For more information on the various types of functions and how they're used, consult the [Rust"] #[doc = " book] or the [Reference]."] #[doc = ""] #[doc = " [`impl`]: keyword.impl.html"] #[doc = " [`extern`]: keyword.extern.html"] #[doc = " [Rust book]: ../book/ch03-03-how-functions-work.html"] #[doc = " [Reference]: ../reference/items/functions.html"] mod fn_keyword { } #[doc (keyword = "for")] #[doc = " Iteration with [`in`], trait implementation with [`impl`], or [higher-ranked trait bounds]"] #[doc = " (`for<'a>`)."] #[doc = ""] #[doc = " The `for` keyword is used in many syntactic locations:"] #[doc = ""] #[doc = " * `for` is used in for-in-loops (see below)."] #[doc = " * `for` is used when implementing traits as in `impl Trait for Type` (see [`impl`] for more info"] #[doc = "   on that)."] #[doc = " * `for` is also used for [higher-ranked trait bounds] as in `for<'a> &'a T: PartialEq<i32>`."] #[doc = ""] #[doc = " for-in-loops, or to be more precise, iterator loops, are a simple syntactic sugar over a common"] #[doc = " practice within Rust, which is to loop over anything that implements [`IntoIterator`] until the"] #[doc = " iterator returned by `.into_iter()` returns `None` (or the loop body uses `break`)."] #[doc = ""] #[doc = " ```rust"] #[doc = " for i in 0..5 {"] #[doc = "     println!(\"{}\", i * 2);"] #[doc = " }"] #[doc = ""] #[doc = " for i in std::iter::repeat(5) {"] #[doc = "     println!(\"turns out {i} never stops being 5\");"] #[doc = "     break; // would loop forever otherwise"] #[doc = " }"] #[doc = ""] #[doc = " 'outer: for x in 5..50 {"] #[doc = "     for y in 0..10 {"] #[doc = "         if x == y {"] #[doc = "             break 'outer;"] #[doc = "         }"] #[doc = "     }"] #[doc = " }"] #[doc = " ```"] #[doc = ""] #[doc = " As shown in the example above, `for` loops (along with all other loops) can be tagged, using"] #[doc = " similar syntax to lifetimes (only visually similar, entirely distinct in practice). Giving the"] #[doc = " same tag to `break` breaks the tagged loop, which is useful for inner loops. It is definitely"] #[doc = " not a goto."] #[doc = ""] #[doc = " A `for` loop expands as shown:"] #[doc = ""] #[doc = " ```rust"] #[doc = " # fn code() { }"] #[doc = " # let iterator = 0..2;"] #[doc = " for loop_variable in iterator {"] #[doc = "     code()"] #[doc = " }"] #[doc = " ```"] #[doc = ""] #[doc = " ```rust"] #[doc = " # fn code() { }"] #[doc = " # let iterator = 0..2;"] #[doc = " {"] #[doc = "     let result = match IntoIterator::into_iter(iterator) {"] #[doc = "         mut iter => loop {"] #[doc = "             match iter.next() {"] #[doc = "                 None => break,"] #[doc = "                 Some(loop_variable) => { code(); },"] #[doc = "             };"] #[doc = "         },"] #[doc = "     };"] #[doc = "     result"] #[doc = " }"] #[doc = " ```"] #[doc = ""] #[doc = " More details on the functionality shown can be seen at the [`IntoIterator`] docs."] #[doc = ""] #[doc = " For more information on for-loops, see the [Rust book] or the [Reference]."] #[doc = ""] #[doc = " See also, [`loop`], [`while`]."] #[doc = ""] #[doc = " [`in`]: keyword.in.html"] #[doc = " [`impl`]: keyword.impl.html"] #[doc = " [`loop`]: keyword.loop.html"] #[doc = " [`while`]: keyword.while.html"] #[doc = " [higher-ranked trait bounds]: ../reference/trait-bounds.html#higher-ranked-trait-bounds"] #[doc = " [Rust book]:"] #[doc = " ../book/ch03-05-control-flow.html#looping-through-a-collection-with-for"] #[doc = " [Reference]: ../reference/expressions/loop-expr.html#iterator-loops"] mod for_keyword { } #[doc (keyword = "if")] #[doc = " Evaluate a block if a condition holds."] #[doc = ""] #[doc = " `if` is a familiar construct to most programmers, and is the main way you'll often do logic in"] #[doc = " your code. However, unlike in most languages, `if` blocks can also act as expressions."] #[doc = ""] #[doc = " ```rust"] #[doc = " # let rude = true;"] #[doc = " if 1 == 2 {"] #[doc = "     println!(\"whoops, mathematics broke\");"] #[doc = " } else {"] #[doc = "     println!(\"everything's fine!\");"] #[doc = " }"] #[doc = ""] #[doc = " let greeting = if rude {"] #[doc = "     \"sup nerd.\""] #[doc = " } else {"] #[doc = "     \"hello, friend!\""] #[doc = " };"] #[doc = ""] #[doc = " if let Ok(x) = \"123\".parse::<i32>() {"] #[doc = "     println!(\"{} double that and you get {}!\", greeting, x * 2);"] #[doc = " }"] #[doc = " ```"] #[doc = ""] #[doc = " Shown above are the three typical forms an `if` block comes in. First is the usual kind of"] #[doc = " thing you'd see in many languages, with an optional `else` block. Second uses `if` as an"] #[doc = " expression, which is only possible if all branches return the same type. An `if` expression can"] #[doc = " be used everywhere you'd expect. The third kind of `if` block is an `if let` block, which"] #[doc = " behaves similarly to using a `match` expression:"] #[doc = ""] #[doc = " ```rust"] #[doc = " if let Some(x) = Some(123) {"] #[doc = "     // code"] #[doc = "     # let _ = x;"] #[doc = " } else {"] #[doc = "     // something else"] #[doc = " }"] #[doc = ""] #[doc = " match Some(123) {"] #[doc = "     Some(x) => {"] #[doc = "         // code"] #[doc = "         # let _ = x;"] #[doc = "     },"] #[doc = "     _ => {"] #[doc = "         // something else"] #[doc = "     },"] #[doc = " }"] #[doc = " ```"] #[doc = ""] #[doc = " Each kind of `if` expression can be mixed and matched as needed."] #[doc = ""] #[doc = " ```rust"] #[doc = " if true == false {"] #[doc = "     println!(\"oh no\");"] #[doc = " } else if \"something\" == \"other thing\" {"] #[doc = "     println!(\"oh dear\");"] #[doc = " } else if let Some(200) = \"blarg\".parse::<i32>().ok() {"] #[doc = "     println!(\"uh oh\");"] #[doc = " } else {"] #[doc = "     println!(\"phew, nothing's broken\");"] #[doc = " }"] #[doc = " ```"] #[doc = ""] #[doc = " The `if` keyword is used in one other place in Rust, namely as a part of pattern matching"] #[doc = " itself, allowing patterns such as `Some(x) if x > 200` to be used."] #[doc = ""] #[doc = " For more information on `if` expressions, see the [Rust book] or the [Reference]."] #[doc = ""] #[doc = " [Rust book]: ../book/ch03-05-control-flow.html#if-expressions"] #[doc = " [Reference]: ../reference/expressions/if-expr.html"] mod if_keyword { } #[doc (keyword = "impl")] #[doc = " Implementations of functionality for a type, or a type implementing some functionality."] #[doc = ""] #[doc = " There are two uses of the keyword `impl`:"] #[doc = "  * An `impl` block is an item that is used to implement some functionality for a type."] #[doc = "  * An `impl Trait` in a type-position can be used to designate a type that implements a trait called `Trait`."] #[doc = ""] #[doc = " # Implementing Functionality for a Type"] #[doc = ""] #[doc = " The `impl` keyword is primarily used to define implementations on types. Inherent"] #[doc = " implementations are standalone, while trait implementations are used to implement traits for"] #[doc = " types, or other traits."] #[doc = ""] #[doc = " An implementation consists of definitions of functions and consts. A function defined in an"] #[doc = " `impl` block can be standalone, meaning it would be called like `Vec::new()`. If the function"] #[doc = " takes `self`, `&self`, or `&mut self` as its first argument, it can also be called using"] #[doc = " method-call syntax, a familiar feature to any object-oriented programmer, like `vec.len()`."] #[doc = ""] #[doc = " ## Inherent Implementations"] #[doc = ""] #[doc = " ```rust"] #[doc = " struct Example {"] #[doc = "     number: i32,"] #[doc = " }"] #[doc = ""] #[doc = " impl Example {"] #[doc = "     fn boo() {"] #[doc = "         println!(\"boo! Example::boo() was called!\");"] #[doc = "     }"] #[doc = ""] #[doc = "     fn answer(&mut self) {"] #[doc = "         self.number += 42;"] #[doc = "     }"] #[doc = ""] #[doc = "     fn get_number(&self) -> i32 {"] #[doc = "         self.number"] #[doc = "     }"] #[doc = " }"] #[doc = " ```"] #[doc = ""] #[doc = " It matters little where an inherent implementation is defined;"] #[doc = " its functionality is in scope wherever its implementing type is."] #[doc = ""] #[doc = " ## Trait Implementations"] #[doc = ""] #[doc = " ```rust"] #[doc = " struct Example {"] #[doc = "     number: i32,"] #[doc = " }"] #[doc = ""] #[doc = " trait Thingy {"] #[doc = "     fn do_thingy(&self);"] #[doc = " }"] #[doc = ""] #[doc = " impl Thingy for Example {"] #[doc = "     fn do_thingy(&self) {"] #[doc = "         println!(\"doing a thing! also, number is {}!\", self.number);"] #[doc = "     }"] #[doc = " }"] #[doc = " ```"] #[doc = ""] #[doc = " It matters little where a trait implementation is defined;"] #[doc = " its functionality can be brought into scope by importing the trait it implements."] #[doc = ""] #[doc = " For more information on implementations, see the [Rust book][book1] or the [Reference]."] #[doc = ""] #[doc = " # Designating a Type that Implements Some Functionality"] #[doc = ""] #[doc = " The other use of the `impl` keyword is in `impl Trait` syntax, which can be understood to mean"] #[doc = " \"any (or some) concrete type that implements Trait\"."] #[doc = " It can be used as the type of a variable declaration,"] #[doc = " in [argument position](https://rust-lang.github.io/rfcs/1951-expand-impl-trait.html)"] #[doc = " or in [return position](https://rust-lang.github.io/rfcs/3425-return-position-impl-trait-in-traits.html)."] #[doc = " One pertinent use case is in working with closures, which have unnameable types."] #[doc = ""] #[doc = " ```rust"] #[doc = " fn thing_returning_closure() -> impl Fn(i32) -> bool {"] #[doc = "     println!(\"here's a closure for you!\");"] #[doc = "     |x: i32| x % 3 == 0"] #[doc = " }"] #[doc = " ```"] #[doc = ""] #[doc = " For more information on `impl Trait` syntax, see the [Rust book][book2]."] #[doc = ""] #[doc = " [book1]: ../book/ch05-03-method-syntax.html"] #[doc = " [Reference]: ../reference/items/implementations.html"] #[doc = " [book2]: ../book/ch10-02-traits.html#returning-types-that-implement-traits"] mod impl_keyword { } #[doc (keyword = "in")] #[doc = " Iterate over a series of values with [`for`]."] #[doc = ""] #[doc = " The expression immediately following `in` must implement the [`IntoIterator`] trait."] #[doc = ""] #[doc = " ## Literal Examples:"] #[doc = ""] #[doc = "    * `for _ in 1..3 {}` - Iterate over an exclusive range up to but excluding 3."] #[doc = "    * `for _ in 1..=3 {}` - Iterate over an inclusive range up to and including 3."] #[doc = ""] #[doc = " (Read more about [range patterns])"] #[doc = ""] #[doc = " [`IntoIterator`]: ../book/ch13-04-performance.html"] #[doc = " [range patterns]: ../reference/patterns.html?highlight=range#range-patterns"] #[doc = " [`for`]: keyword.for.html"] #[doc = ""] #[doc = " The other use of `in` is with the keyword `pub`. It allows users to declare an item as visible"] #[doc = " only within a given scope."] #[doc = ""] #[doc = " ## Literal Example:"] #[doc = ""] #[doc = "    * `pub(in crate::outer_mod) fn outer_mod_visible_fn() {}` - fn is visible in `outer_mod`"] #[doc = ""] #[doc = " Starting with the 2018 edition, paths for `pub(in path)` must start with `crate`, `self` or"] #[doc = " `super`. The 2015 edition may also use paths starting with `::` or modules from the crate root."] #[doc = ""] #[doc = " For more information, see the [Reference]."] #[doc = ""] #[doc = " [Reference]: ../reference/visibility-and-privacy.html#pubin-path-pubcrate-pubsuper-and-pubself"] mod in_keyword { } #[doc (keyword = "let")] #[doc = " Bind a value to a variable."] #[doc = ""] #[doc = " The primary use for the `let` keyword is in `let` statements, which are used to introduce a new"] #[doc = " set of variables into the current scope, as given by a pattern."] #[doc = ""] #[doc = " ```rust"] #[doc = " # #![allow(unused_assignments)]"] #[doc = " let thing1: i32 = 100;"] #[doc = " let thing2 = 200 + thing1;"] #[doc = ""] #[doc = " let mut changing_thing = true;"] #[doc = " changing_thing = false;"] #[doc = ""] #[doc = " let (part1, part2) = (\"first\", \"second\");"] #[doc = ""] #[doc = " struct Example {"] #[doc = "     a: bool,"] #[doc = "     b: u64,"] #[doc = " }"] #[doc = ""] #[doc = " let Example { a, b: _ } = Example {"] #[doc = "     a: true,"] #[doc = "     b: 10004,"] #[doc = " };"] #[doc = " assert!(a);"] #[doc = " ```"] #[doc = ""] #[doc = " The pattern is most commonly a single variable, which means no pattern matching is done and"] #[doc = " the expression given is bound to the variable. Apart from that, patterns used in `let` bindings"] #[doc = " can be as complicated as needed, given that the pattern is exhaustive. See the [Rust"] #[doc = " book][book1] for more information on pattern matching. The type of the pattern is optionally"] #[doc = " given afterwards, but if left blank is automatically inferred by the compiler if possible."] #[doc = ""] #[doc = " Variables in Rust are immutable by default, and require the `mut` keyword to be made mutable."] #[doc = ""] #[doc = " Multiple variables can be defined with the same name, known as shadowing. This doesn't affect"] #[doc = " the original variable in any way beyond being unable to directly access it beyond the point of"] #[doc = " shadowing. It continues to remain in scope, getting dropped only when it falls out of scope."] #[doc = " Shadowed variables don't need to have the same type as the variables shadowing them."] #[doc = ""] #[doc = " ```rust"] #[doc = " let shadowing_example = true;"] #[doc = " let shadowing_example = 123.4;"] #[doc = " let shadowing_example = shadowing_example as u32;"] #[doc = " let mut shadowing_example = format!(\"cool! {shadowing_example}\");"] #[doc = " shadowing_example += \" something else!\"; // not shadowing"] #[doc = " ```"] #[doc = ""] #[doc = " Other places the `let` keyword is used include along with [`if`], in the form of `if let`"] #[doc = " expressions. They're useful if the pattern being matched isn't exhaustive, such as with"] #[doc = " enumerations. `while let` also exists, which runs a loop with a pattern matched value until"] #[doc = " that pattern can't be matched."] #[doc = ""] #[doc = " For more information on the `let` keyword, see the [Rust book][book2] or the [Reference]"] #[doc = ""] #[doc = " [book1]: ../book/ch06-02-match.html"] #[doc = " [`if`]: keyword.if.html"] #[doc = " [book2]: ../book/ch18-01-all-the-places-for-patterns.html#let-statements"] #[doc = " [Reference]: ../reference/statements.html#let-statements"] mod let_keyword { } #[doc (keyword = "loop")] #[doc = " Loop indefinitely."] #[doc = ""] #[doc = " `loop` is used to define the simplest kind of loop supported in Rust. It runs the code inside"] #[doc = " it until the code uses `break` or the program exits."] #[doc = ""] #[doc = " ```rust"] #[doc = " loop {"] #[doc = "     println!(\"hello world forever!\");"] #[doc = "     # break;"] #[doc = " }"] #[doc = ""] #[doc = " let mut i = 1;"] #[doc = " loop {"] #[doc = "     println!(\"i is {i}\");"] #[doc = "     if i > 100 {"] #[doc = "         break;"] #[doc = "     }"] #[doc = "     i *= 2;"] #[doc = " }"] #[doc = " assert_eq!(i, 128);"] #[doc = " ```"] #[doc = ""] #[doc = " Unlike the other kinds of loops in Rust (`while`, `while let`, and `for`), loops can be used as"] #[doc = " expressions that return values via `break`."] #[doc = ""] #[doc = " ```rust"] #[doc = " let mut i = 1;"] #[doc = " let something = loop {"] #[doc = "     i *= 2;"] #[doc = "     if i > 100 {"] #[doc = "         break i;"] #[doc = "     }"] #[doc = " };"] #[doc = " assert_eq!(something, 128);"] #[doc = " ```"] #[doc = ""] #[doc = " Every `break` in a loop has to have the same type. When it's not explicitly giving something,"] #[doc = " `break;` returns `()`."] #[doc = ""] #[doc = " For more information on `loop` and loops in general, see the [Reference]."] #[doc = ""] #[doc = " See also, [`for`], [`while`]."] #[doc = ""] #[doc = " [`for`]: keyword.for.html"] #[doc = " [`while`]: keyword.while.html"] #[doc = " [Reference]: ../reference/expressions/loop-expr.html"] mod loop_keyword { } #[doc (keyword = "match")] #[doc = " Control flow based on pattern matching."] #[doc = ""] #[doc = " `match` can be used to run code conditionally. Every pattern must"] #[doc = " be handled exhaustively either explicitly or by using wildcards like"] #[doc = " `_` in the `match`. Since `match` is an expression, values can also be"] #[doc = " returned."] #[doc = ""] #[doc = " ```rust"] #[doc = " let opt = Option::None::<usize>;"] #[doc = " let x = match opt {"] #[doc = "     Some(int) => int,"] #[doc = "     None => 10,"] #[doc = " };"] #[doc = " assert_eq!(x, 10);"] #[doc = ""] #[doc = " let a_number = Option::Some(10);"] #[doc = " match a_number {"] #[doc = "     Some(x) if x <= 5 => println!(\"0 to 5 num = {x}\"),"] #[doc = "     Some(x @ 6..=10) => println!(\"6 to 10 num = {x}\"),"] #[doc = "     None => panic!(),"] #[doc = "     // all other numbers"] #[doc = "     _ => panic!(),"] #[doc = " }"] #[doc = " ```"] #[doc = ""] #[doc = " `match` can be used to gain access to the inner members of an enum"] #[doc = " and use them directly."] #[doc = ""] #[doc = " ```rust"] #[doc = " enum Outer {"] #[doc = "     Double(Option<u8>, Option<String>),"] #[doc = "     Single(Option<u8>),"] #[doc = "     Empty"] #[doc = " }"] #[doc = ""] #[doc = " let get_inner = Outer::Double(None, Some(String::new()));"] #[doc = " match get_inner {"] #[doc = "     Outer::Double(None, Some(st)) => println!(\"{st}\"),"] #[doc = "     Outer::Single(opt) => println!(\"{opt:?}\"),"] #[doc = "     _ => panic!(),"] #[doc = " }"] #[doc = " ```"] #[doc = ""] #[doc = " For more information on `match` and matching in general, see the [Reference]."] #[doc = ""] #[doc = " [Reference]: ../reference/expressions/match-expr.html"] mod match_keyword { } #[doc (keyword = "mod")] #[doc = " Organize code into [modules]."] #[doc = ""] #[doc = " Use `mod` to create new [modules] to encapsulate code, including other"] #[doc = " modules:"] #[doc = ""] #[doc = " ```"] #[doc = " mod foo {"] #[doc = "     mod bar {"] #[doc = "         type MyType = (u8, u8);"] #[doc = "         fn baz() {}"] #[doc = "     }"] #[doc = " }"] #[doc = " ```"] #[doc = ""] #[doc = " Like [`struct`]s and [`enum`]s, a module and its content are private by"] #[doc = " default, inaccessible to code outside of the module."] #[doc = ""] #[doc = " To learn more about allowing access, see the documentation for the [`pub`]"] #[doc = " keyword."] #[doc = ""] #[doc = " [`enum`]: keyword.enum.html"] #[doc = " [`pub`]: keyword.pub.html"] #[doc = " [`struct`]: keyword.struct.html"] #[doc = " [modules]: ../reference/items/modules.html"] mod mod_keyword { } #[doc (keyword = "move")] #[doc = " Capture a [closure]'s environment by value."] #[doc = ""] #[doc = " `move` converts any variables captured by reference or mutable reference"] #[doc = " to variables captured by value."] #[doc = ""] #[doc = " ```rust"] #[doc = " let data = vec![1, 2, 3];"] #[doc = " let closure = move || println!(\"captured {data:?} by value\");"] #[doc = ""] #[doc = " // data is no longer available, it is owned by the closure"] #[doc = " ```"] #[doc = ""] #[doc = " Note: `move` closures may still implement [`Fn`] or [`FnMut`], even though"] #[doc = " they capture variables by `move`. This is because the traits implemented by"] #[doc = " a closure type are determined by *what* the closure does with captured"] #[doc = " values, not *how* it captures them:"] #[doc = ""] #[doc = " ```rust"] #[doc = " fn create_fn() -> impl Fn() {"] #[doc = "     let text = \"Fn\".to_owned();"] #[doc = "     move || println!(\"This is a: {text}\")"] #[doc = " }"] #[doc = ""] #[doc = " let fn_plain = create_fn();"] #[doc = " fn_plain();"] #[doc = " ```"] #[doc = ""] #[doc = " `move` is often used when [threads] are involved."] #[doc = ""] #[doc = " ```rust"] #[doc = " let data = vec![1, 2, 3];"] #[doc = ""] #[doc = " std::thread::spawn(move || {"] #[doc = "     println!(\"captured {data:?} by value\")"] #[doc = " }).join().unwrap();"] #[doc = ""] #[doc = " // data was moved to the spawned thread, so we cannot use it here"] #[doc = " ```"] #[doc = ""] #[doc = " `move` is also valid before an async block."] #[doc = ""] #[doc = " ```rust"] #[doc = " let capture = \"hello\".to_owned();"] #[doc = " let block = async move {"] #[doc = "     println!(\"rust says {capture} from async block\");"] #[doc = " };"] #[doc = " ```"] #[doc = ""] #[doc = " For more information on the `move` keyword, see the [closures][closure] section"] #[doc = " of the Rust book or the [threads] section."] #[doc = ""] #[doc = " [closure]: ../book/ch13-01-closures.html"] #[doc = " [threads]: ../book/ch16-01-threads.html#using-move-closures-with-threads"] mod move_keyword { } #[doc (keyword = "mut")] #[doc = " A mutable variable, reference, or pointer."] #[doc = ""] #[doc = " `mut` can be used in several situations. The first is mutable variables,"] #[doc = " which can be used anywhere you can bind a value to a variable name. Some"] #[doc = " examples:"] #[doc = ""] #[doc = " ```rust"] #[doc = " // A mutable variable in the parameter list of a function."] #[doc = " fn foo(mut x: u8, y: u8) -> u8 {"] #[doc = "     x += y;"] #[doc = "     x"] #[doc = " }"] #[doc = ""] #[doc = " // Modifying a mutable variable."] #[doc = " # #[allow(unused_assignments)]"] #[doc = " let mut a = 5;"] #[doc = " a = 6;"] #[doc = ""] #[doc = " assert_eq!(foo(3, 4), 7);"] #[doc = " assert_eq!(a, 6);"] #[doc = " ```"] #[doc = ""] #[doc = " The second is mutable references. They can be created from `mut` variables"] #[doc = " and must be unique: no other variables can have a mutable reference, nor a"] #[doc = " shared reference."] #[doc = ""] #[doc = " ```rust"] #[doc = " // Taking a mutable reference."] #[doc = " fn push_two(v: &mut Vec<u8>) {"] #[doc = "     v.push(2);"] #[doc = " }"] #[doc = ""] #[doc = " // A mutable reference cannot be taken to a non-mutable variable."] #[doc = " let mut v = vec![0, 1];"] #[doc = " // Passing a mutable reference."] #[doc = " push_two(&mut v);"] #[doc = ""] #[doc = " assert_eq!(v, vec![0, 1, 2]);"] #[doc = " ```"] #[doc = ""] #[doc = " ```rust,compile_fail,E0502"] #[doc = " let mut v = vec![0, 1];"] #[doc = " let mut_ref_v = &mut v;"] #[doc = " # #[allow(unused)]"] #[doc = " let ref_v = &v;"] #[doc = " mut_ref_v.push(2);"] #[doc = " ```"] #[doc = ""] #[doc = " Mutable raw pointers work much like mutable references, with the added"] #[doc = " possibility of not pointing to a valid object. The syntax is `*mut Type`."] #[doc = ""] #[doc = " More information on mutable references and pointers can be found in the [Reference]."] #[doc = ""] #[doc = " [Reference]: ../reference/types/pointer.html#mutable-references-mut"] mod mut_keyword { } #[doc (keyword = "pub")] #[doc = " Make an item visible to others."] #[doc = ""] #[doc = " The keyword `pub` makes any module, function, or data structure accessible from inside"] #[doc = " of external modules. The `pub` keyword may also be used in a `use` declaration to re-export"] #[doc = " an identifier from a namespace."] #[doc = ""] #[doc = " For more information on the `pub` keyword, please see the visibility section"] #[doc = " of the [reference] and for some examples, see [Rust by Example]."] #[doc = ""] #[doc = " [reference]:../reference/visibility-and-privacy.html?highlight=pub#visibility-and-privacy"] #[doc = " [Rust by Example]:../rust-by-example/mod/visibility.html"] mod pub_keyword { } #[doc (keyword = "ref")] #[doc = " Bind by reference during pattern matching."] #[doc = ""] #[doc = " `ref` annotates pattern bindings to make them borrow rather than move."] #[doc = " It is **not** a part of the pattern as far as matching is concerned: it does"] #[doc = " not affect *whether* a value is matched, only *how* it is matched."] #[doc = ""] #[doc = " By default, [`match`] statements consume all they can, which can sometimes"] #[doc = " be a problem, when you don't really need the value to be moved and owned:"] #[doc = ""] #[doc = " ```compile_fail,E0382"] #[doc = " let maybe_name = Some(String::from(\"Alice\"));"] #[doc = " // The variable 'maybe_name' is consumed here ..."] #[doc = " match maybe_name {"] #[doc = "     Some(n) => println!(\"Hello, {n}\"),"] #[doc = "     _ => println!(\"Hello, world\"),"] #[doc = " }"] #[doc = " // ... and is now unavailable."] #[doc = " println!(\"Hello again, {}\", maybe_name.unwrap_or(\"world\".into()));"] #[doc = " ```"] #[doc = ""] #[doc = " Using the `ref` keyword, the value is only borrowed, not moved, making it"] #[doc = " available for use after the [`match`] statement:"] #[doc = ""] #[doc = " ```"] #[doc = " let maybe_name = Some(String::from(\"Alice\"));"] #[doc = " // Using `ref`, the value is borrowed, not moved ..."] #[doc = " match maybe_name {"] #[doc = "     Some(ref n) => println!(\"Hello, {n}\"),"] #[doc = "     _ => println!(\"Hello, world\"),"] #[doc = " }"] #[doc = " // ... so it's available here!"] #[doc = " println!(\"Hello again, {}\", maybe_name.unwrap_or(\"world\".into()));"] #[doc = " ```"] #[doc = ""] #[doc = " # `&` vs `ref`"] #[doc = ""] #[doc = " - `&` denotes that your pattern expects a reference to an object. Hence `&`"] #[doc = " is a part of said pattern: `&Foo` matches different objects than `Foo` does."] #[doc = ""] #[doc = " - `ref` indicates that you want a reference to an unpacked value. It is not"] #[doc = " matched against: `Foo(ref foo)` matches the same objects as `Foo(foo)`."] #[doc = ""] #[doc = " See also the [Reference] for more information."] #[doc = ""] #[doc = " [`match`]: keyword.match.html"] #[doc = " [Reference]: ../reference/patterns.html#identifier-patterns"] mod ref_keyword { } #[doc (keyword = "return")] #[doc = " Returns a value from a function."] #[doc = ""] #[doc = " A `return` marks the end of an execution path in a function:"] #[doc = ""] #[doc = " ```"] #[doc = " fn foo() -> i32 {"] #[doc = "     return 3;"] #[doc = " }"] #[doc = " assert_eq!(foo(), 3);"] #[doc = " ```"] #[doc = ""] #[doc = " `return` is not needed when the returned value is the last expression in the"] #[doc = " function. In this case the `;` is omitted:"] #[doc = ""] #[doc = " ```"] #[doc = " fn foo() -> i32 {"] #[doc = "     3"] #[doc = " }"] #[doc = " assert_eq!(foo(), 3);"] #[doc = " ```"] #[doc = ""] #[doc = " `return` returns from the function immediately (an \"early return\"):"] #[doc = ""] #[doc = " ```no_run"] #[doc = " use std::fs::File;"] #[doc = " use std::io::{Error, ErrorKind, Read, Result};"] #[doc = ""] #[doc = " fn main() -> Result<()> {"] #[doc = "     let mut file = match File::open(\"foo.txt\") {"] #[doc = "         Ok(f) => f,"] #[doc = "         Err(e) => return Err(e),"] #[doc = "     };"] #[doc = ""] #[doc = "     let mut contents = String::new();"] #[doc = "     let size = match file.read_to_string(&mut contents) {"] #[doc = "         Ok(s) => s,"] #[doc = "         Err(e) => return Err(e),"] #[doc = "     };"] #[doc = ""] #[doc = "     if contents.contains(\"impossible!\") {"] #[doc = "         return Err(Error::new(ErrorKind::Other, \"oh no!\"));"] #[doc = "     }"] #[doc = ""] #[doc = "     if size > 9000 {"] #[doc = "         return Err(Error::new(ErrorKind::Other, \"over 9000!\"));"] #[doc = "     }"] #[doc = ""] #[doc = "     assert_eq!(contents, \"Hello, world!\");"] #[doc = "     Ok(())"] #[doc = " }"] #[doc = " ```"] #[doc = ""] #[doc = " Within [closures] and [`async`] blocks, `return` returns a value from within the closure or"] #[doc = " `async` block, not from the parent function:"] #[doc = ""] #[doc = " ```rust"] #[doc = " fn foo() -> i32 {"] #[doc = "     let closure = || {"] #[doc = "         return 5;"] #[doc = "     };"] #[doc = ""] #[doc = "     let future = async {"] #[doc = "         return 10;"] #[doc = "     };"] #[doc = ""] #[doc = "     return 15;"] #[doc = " }"] #[doc = ""] #[doc = " assert_eq!(foo(), 15);"] #[doc = " ```"] #[doc = ""] #[doc = " [closures]: ../book/ch13-01-closures.html"] #[doc = " [`async`]: ../std/keyword.async.html"] mod return_keyword { } #[doc (keyword = "become")] #[doc = " Perform a tail-call of a function."] #[doc = ""] #[doc = " <div class=\"warning\">"] #[doc = ""] #[doc = " `feature(explicit_tail_calls)` is currently incomplete and may not work properly."] #[doc = " </div>"] #[doc = ""] #[doc = " When tail calling a function, instead of its stack frame being added to the"] #[doc = " stack, the stack frame of the caller is directly replaced with the callee's."] #[doc = " This means that as long as a loop in a call graph only uses tail calls, the"] #[doc = " stack growth will be bounded."] #[doc = ""] #[doc = " This is useful for writing functional-style code (since it prevents recursion"] #[doc = " from exhausting resources) or for code optimization (since a tail call"] #[doc = " *might* be cheaper than a normal call, tail calls can be used in a similar"] #[doc = " manner to computed goto)."] #[doc = ""] #[doc = " Example of using `become` to implement functional-style `fold`:"] #[doc = " ```"] #[doc = " #![feature(explicit_tail_calls)]"] #[doc = " #![expect(incomplete_features)]"] #[doc = ""] #[doc = " fn fold<T: Copy, S>(slice: &[T], init: S, f: impl Fn(S, T) -> S) -> S {"] #[doc = "     match slice {"] #[doc = "         // without `become`, on big inputs this could easily overflow the"] #[doc = "         // stack. using a tail call guarantees that the stack will not grow unboundedly"] #[doc = "         [first, rest @ ..] => become fold(rest, f(init, *first), f),"] #[doc = "         [] => init,"] #[doc = "     }"] #[doc = " }"] #[doc = " ```"] #[doc = ""] #[doc = " Compilers can already perform \"tail call optimization\" -- they can replace normal"] #[doc = " calls with tail calls, although there are no guarantees that this will be done."] #[doc = " However, to perform TCO, the call needs to be the last thing that happens"] #[doc = " in the functions and be returned from it. This requirement is often broken"] #[doc = " by drop code for locals, which is run after computing the return expression:"] #[doc = ""] #[doc = " ```"] #[doc = " fn example() {"] #[doc = "     let string = \"meow\".to_owned();"] #[doc = "     println!(\"{string}\");"] #[doc = "     return help(); // this is *not* the last thing that happens in `example`..."] #[doc = " }"] #[doc = ""] #[doc = " // ... because it is desugared to this:"] #[doc = " fn example_desugared() {"] #[doc = "     let string = \"meow\".to_owned();"] #[doc = "     println!(\"{string}\");"] #[doc = "     let tmp = help();"] #[doc = "     drop(string);"] #[doc = "     return tmp;"] #[doc = " }"] #[doc = ""] #[doc = " fn help() {}"] #[doc = " ```"] #[doc = ""] #[doc = " For this reason, `become` also changes the drop order, such that locals are"] #[doc = " dropped *before* evaluating the call."] #[doc = ""] #[doc = " In order to guarantee that the compiler can perform a tail call, `become`"] #[doc = " currently has these requirements:"] #[doc = " 1. callee and caller must have the same ABI, arguments, and return type"] #[doc = " 2. callee and caller must not have varargs"] #[doc = " 3. caller must not be marked with `#[track_caller]`"] #[doc = "    - callee is allowed to be marked with `#[track_caller]` as otherwise"] #[doc = "      adding `#[track_caller]` would be a breaking change. if callee is"] #[doc = "      marked with `#[track_caller]` a tail call is not guaranteed."] #[doc = " 4. callee and caller cannot be a closure"] #[doc = "    (unless it's coerced to a function pointer)"] #[doc = ""] #[doc = " It is possible to tail-call a function pointer:"] #[doc = " ```"] #[doc = " #![feature(explicit_tail_calls)]"] #[doc = " #![expect(incomplete_features)]"] #[doc = ""] #[doc = " #[derive(Copy, Clone)]"] #[doc = " enum Inst { Inc, Dec }"] #[doc = ""] #[doc = " fn dispatch(stream: &[Inst], state: u32) -> u32 {"] #[doc = "     const TABLE: &[fn(&[Inst], u32) -> u32] = &[increment, decrement];"] #[doc = "     match stream {"] #[doc = "         [inst, rest @ ..] => become TABLE[*inst as usize](rest, state),"] #[doc = "         [] => state,"] #[doc = "     }"] #[doc = " }"] #[doc = ""] #[doc = " fn increment(stream: &[Inst], state: u32) -> u32 {"] #[doc = "     become dispatch(stream, state + 1)"] #[doc = " }"] #[doc = ""] #[doc = " fn decrement(stream: &[Inst], state: u32) -> u32 {"] #[doc = "     become dispatch(stream, state - 1)"] #[doc = " }"] #[doc = ""] #[doc = " let program = &[Inst::Inc, Inst::Inc, Inst::Dec, Inst::Inc];"] #[doc = " assert_eq!(dispatch(program, 0), 2);"] #[doc = " ```"] mod become_keyword { } #[doc (keyword = "self")] #[doc = " The receiver of a method, or the current module."] #[doc = ""] #[doc = " `self` is used in two situations: referencing the current module and marking"] #[doc = " the receiver of a method."] #[doc = ""] #[doc = " In paths, `self` can be used to refer to the current module, either in a"] #[doc = " [`use`] statement or in a path to access an element:"] #[doc = ""] #[doc = " ```"] #[doc = " # #![allow(unused_imports)]"] #[doc = " use std::io::{self, Read};"] #[doc = " ```"] #[doc = ""] #[doc = " Is functionally the same as:"] #[doc = ""] #[doc = " ```"] #[doc = " # #![allow(unused_imports)]"] #[doc = " use std::io;"] #[doc = " use std::io::Read;"] #[doc = " ```"] #[doc = ""] #[doc = " Using `self` to access an element in the current module:"] #[doc = ""] #[doc = " ```"] #[doc = " # #![allow(dead_code)]"] #[doc = " # fn main() {}"] #[doc = " fn foo() {}"] #[doc = " fn bar() {"] #[doc = "     self::foo()"] #[doc = " }"] #[doc = " ```"] #[doc = ""] #[doc = " `self` as the current receiver for a method allows to omit the parameter"] #[doc = " type most of the time. With the exception of this particularity, `self` is"] #[doc = " used much like any other parameter:"] #[doc = ""] #[doc = " ```"] #[doc = " struct Foo(i32);"] #[doc = ""] #[doc = " impl Foo {"] #[doc = "     // No `self`."] #[doc = "     fn new() -> Self {"] #[doc = "         Self(0)"] #[doc = "     }"] #[doc = ""] #[doc = "     // Consuming `self`."] #[doc = "     fn consume(self) -> Self {"] #[doc = "         Self(self.0 + 1)"] #[doc = "     }"] #[doc = ""] #[doc = "     // Borrowing `self`."] #[doc = "     fn borrow(&self) -> &i32 {"] #[doc = "         &self.0"] #[doc = "     }"] #[doc = ""] #[doc = "     // Borrowing `self` mutably."] #[doc = "     fn borrow_mut(&mut self) -> &mut i32 {"] #[doc = "         &mut self.0"] #[doc = "     }"] #[doc = " }"] #[doc = ""] #[doc = " // This method must be called with a `Type::` prefix."] #[doc = " let foo = Foo::new();"] #[doc = " assert_eq!(foo.0, 0);"] #[doc = ""] #[doc = " // Those two calls produces the same result."] #[doc = " let foo = Foo::consume(foo);"] #[doc = " assert_eq!(foo.0, 1);"] #[doc = " let foo = foo.consume();"] #[doc = " assert_eq!(foo.0, 2);"] #[doc = ""] #[doc = " // Borrowing is handled automatically with the second syntax."] #[doc = " let borrow_1 = Foo::borrow(&foo);"] #[doc = " let borrow_2 = foo.borrow();"] #[doc = " assert_eq!(borrow_1, borrow_2);"] #[doc = ""] #[doc = " // Borrowing mutably is handled automatically too with the second syntax."] #[doc = " let mut foo = Foo::new();"] #[doc = " *Foo::borrow_mut(&mut foo) += 1;"] #[doc = " assert_eq!(foo.0, 1);"] #[doc = " *foo.borrow_mut() += 1;"] #[doc = " assert_eq!(foo.0, 2);"] #[doc = " ```"] #[doc = ""] #[doc = " Note that this automatic conversion when calling `foo.method()` is not"] #[doc = " limited to the examples above. See the [Reference] for more information."] #[doc = ""] #[doc = " [`use`]: keyword.use.html"] #[doc = " [Reference]: ../reference/items/associated-items.html#methods"] mod self_keyword { } #[doc (alias = "Self")] #[doc (keyword = "SelfTy")] #[doc = " The implementing type within a [`trait`] or [`impl`] block, or the current type within a type"] #[doc = " definition."] #[doc = ""] #[doc = " Within a type definition:"] #[doc = ""] #[doc = " ```"] #[doc = " # #![allow(dead_code)]"] #[doc = " struct Node {"] #[doc = "     elem: i32,"] #[doc = "     // `Self` is a `Node` here."] #[doc = "     next: Option<Box<Self>>,"] #[doc = " }"] #[doc = " ```"] #[doc = ""] #[doc = " In an [`impl`] block:"] #[doc = ""] #[doc = " ```"] #[doc = " struct Foo(i32);"] #[doc = ""] #[doc = " impl Foo {"] #[doc = "     fn new() -> Self {"] #[doc = "         Self(0)"] #[doc = "     }"] #[doc = " }"] #[doc = ""] #[doc = " assert_eq!(Foo::new().0, Foo(0).0);"] #[doc = " ```"] #[doc = ""] #[doc = " Generic parameters are implicit with `Self`:"] #[doc = ""] #[doc = " ```"] #[doc = " # #![allow(dead_code)]"] #[doc = " struct Wrap<T> {"] #[doc = "     elem: T,"] #[doc = " }"] #[doc = ""] #[doc = " impl<T> Wrap<T> {"] #[doc = "     fn new(elem: T) -> Self {"] #[doc = "         Self { elem }"] #[doc = "     }"] #[doc = " }"] #[doc = " ```"] #[doc = ""] #[doc = " In a [`trait`] definition and related [`impl`] block:"] #[doc = ""] #[doc = " ```"] #[doc = " trait Example {"] #[doc = "     fn example() -> Self;"] #[doc = " }"] #[doc = ""] #[doc = " struct Foo(i32);"] #[doc = ""] #[doc = " impl Example for Foo {"] #[doc = "     fn example() -> Self {"] #[doc = "         Self(42)"] #[doc = "     }"] #[doc = " }"] #[doc = ""] #[doc = " assert_eq!(Foo::example().0, Foo(42).0);"] #[doc = " ```"] #[doc = ""] #[doc = " [`impl`]: keyword.impl.html"] #[doc = " [`trait`]: keyword.trait.html"] mod self_upper_keyword { } #[doc (keyword = "static")] #[doc = " A static item is a value which is valid for the entire duration of your"] #[doc = " program (a `'static` lifetime)."] #[doc = ""] #[doc = " On the surface, `static` items seem very similar to [`const`]s: both contain"] #[doc = " a value, both require type annotations and both can only be initialized with"] #[doc = " constant functions and values. However, `static`s are notably different in"] #[doc = " that they represent a location in memory. That means that you can have"] #[doc = " references to `static` items and potentially even modify them, making them"] #[doc = " essentially global variables."] #[doc = ""] #[doc = " Static items do not call [`drop`] at the end of the program."] #[doc = ""] #[doc = " There are two types of `static` items: those declared in association with"] #[doc = " the [`mut`] keyword and those without."] #[doc = ""] #[doc = " Static items cannot be moved:"] #[doc = ""] #[doc = " ```rust,compile_fail,E0507"] #[doc = " static VEC: Vec<u32> = vec![];"] #[doc = ""] #[doc = " fn move_vec(v: Vec<u32>) -> Vec<u32> {"] #[doc = "     v"] #[doc = " }"] #[doc = ""] #[doc = " // This line causes an error"] #[doc = " move_vec(VEC);"] #[doc = " ```"] #[doc = ""] #[doc = " # Simple `static`s"] #[doc = ""] #[doc = " Accessing non-[`mut`] `static` items is considered safe, but some"] #[doc = " restrictions apply. Most notably, the type of a `static` value needs to"] #[doc = " implement the [`Sync`] trait, ruling out interior mutability containers"] #[doc = " like [`RefCell`]. See the [Reference] for more information."] #[doc = ""] #[doc = " ```rust"] #[doc = " static FOO: [i32; 5] = [1, 2, 3, 4, 5];"] #[doc = ""] #[doc = " let r1 = &FOO as *const _;"] #[doc = " let r2 = &FOO as *const _;"] #[doc = " // With a strictly read-only static, references will have the same address"] #[doc = " assert_eq!(r1, r2);"] #[doc = " // A static item can be used just like a variable in many cases"] #[doc = " println!(\"{FOO:?}\");"] #[doc = " ```"] #[doc = ""] #[doc = " # Mutable `static`s"] #[doc = ""] #[doc = " If a `static` item is declared with the [`mut`] keyword, then it is allowed"] #[doc = " to be modified by the program. However, accessing mutable `static`s can"] #[doc = " cause undefined behavior in a number of ways, for example due to data races"] #[doc = " in a multithreaded context. As such, all accesses to mutable `static`s"] #[doc = " require an [`unsafe`] block."] #[doc = ""] #[doc = " When possible, it's often better to use a non-mutable `static` with an"] #[doc = " interior mutable type such as [`Mutex`], [`OnceLock`], or an [atomic]."] #[doc = ""] #[doc = " Despite their unsafety, mutable `static`s are necessary in many contexts:"] #[doc = " they can be used to represent global state shared by the whole program or in"] #[doc = " [`extern`] blocks to bind to variables from C libraries."] #[doc = ""] #[doc = " In an [`extern`] block:"] #[doc = ""] #[doc = " ```rust,no_run"] #[doc = " # #![allow(dead_code)]"] #[doc = " unsafe extern \"C\" {"] #[doc = "     static mut ERROR_MESSAGE: *mut std::os::raw::c_char;"] #[doc = " }"] #[doc = " ```"] #[doc = ""] #[doc = " Mutable `static`s, just like simple `static`s, have some restrictions that"] #[doc = " apply to them. See the [Reference] for more information."] #[doc = ""] #[doc = " [`const`]: keyword.const.html"] #[doc = " [`extern`]: keyword.extern.html"] #[doc = " [`mut`]: keyword.mut.html"] #[doc = " [`unsafe`]: keyword.unsafe.html"] #[doc = " [`Mutex`]: sync::Mutex"] #[doc = " [`OnceLock`]: sync::OnceLock"] #[doc = " [`RefCell`]: cell::RefCell"] #[doc = " [atomic]: sync::atomic"] #[doc = " [Reference]: ../reference/items/static-items.html"] mod static_keyword { } #[doc (keyword = "struct")] #[doc = " A type that is composed of other types."] #[doc = ""] #[doc = " Structs in Rust come in three flavors: Structs with named fields, tuple structs, and unit"] #[doc = " structs."] #[doc = ""] #[doc = " ```rust"] #[doc = " struct Regular {"] #[doc = "     field1: f32,"] #[doc = "     field2: String,"] #[doc = "     pub field3: bool"] #[doc = " }"] #[doc = ""] #[doc = " struct Tuple(u32, String);"] #[doc = ""] #[doc = " struct Unit;"] #[doc = " ```"] #[doc = ""] #[doc = " Regular structs are the most commonly used. Each field defined within them has a name and a"] #[doc = " type, and once defined can be accessed using `example_struct.field` syntax. The fields of a"] #[doc = " struct share its mutability, so `foo.bar = 2;` would only be valid if `foo` was mutable. Adding"] #[doc = " `pub` to a field makes it visible to code in other modules, as well as allowing it to be"] #[doc = " directly accessed and modified."] #[doc = ""] #[doc = " Tuple structs are similar to regular structs, but its fields have no names. They are used like"] #[doc = " tuples, with deconstruction possible via `let TupleStruct(x, y) = foo;` syntax. For accessing"] #[doc = " individual variables, the same syntax is used as with regular tuples, namely `foo.0`, `foo.1`,"] #[doc = " etc, starting at zero."] #[doc = ""] #[doc = " Unit structs are most commonly used as marker. They have a size of zero bytes, but unlike empty"] #[doc = " enums they can be instantiated, making them isomorphic to the unit type `()`. Unit structs are"] #[doc = " useful when you need to implement a trait on something, but don't need to store any data inside"] #[doc = " it."] #[doc = ""] #[doc = " # Instantiation"] #[doc = ""] #[doc = " Structs can be instantiated in different ways, all of which can be mixed and"] #[doc = " matched as needed. The most common way to make a new struct is via a constructor method such as"] #[doc = " `new()`, but when that isn't available (or you're writing the constructor itself), struct"] #[doc = " literal syntax is used:"] #[doc = ""] #[doc = " ```rust"] #[doc = " # struct Foo { field1: f32, field2: String, etc: bool }"] #[doc = " let example = Foo {"] #[doc = "     field1: 42.0,"] #[doc = "     field2: \"blah\".to_string(),"] #[doc = "     etc: true,"] #[doc = " };"] #[doc = " ```"] #[doc = ""] #[doc = " It's only possible to directly instantiate a struct using struct literal syntax when all of its"] #[doc = " fields are visible to you."] #[doc = ""] #[doc = " There are a handful of shortcuts provided to make writing constructors more convenient, most"] #[doc = " common of which is the Field Init shorthand. When there is a variable and a field of the same"] #[doc = " name, the assignment can be simplified from `field: field` into simply `field`. The following"] #[doc = " example of a hypothetical constructor demonstrates this:"] #[doc = ""] #[doc = " ```rust"] #[doc = " struct User {"] #[doc = "     name: String,"] #[doc = "     admin: bool,"] #[doc = " }"] #[doc = ""] #[doc = " impl User {"] #[doc = "     pub fn new(name: String) -> Self {"] #[doc = "         Self {"] #[doc = "             name,"] #[doc = "             admin: false,"] #[doc = "         }"] #[doc = "     }"] #[doc = " }"] #[doc = " ```"] #[doc = ""] #[doc = " Another shortcut for struct instantiation is available, used when you need to make a new"] #[doc = " struct that has the same values as most of a previous struct of the same type, called struct"] #[doc = " update syntax:"] #[doc = ""] #[doc = " ```rust"] #[doc = " # struct Foo { field1: String, field2: () }"] #[doc = " # let thing = Foo { field1: \"\".to_string(), field2: () };"] #[doc = " let updated_thing = Foo {"] #[doc = "     field1: \"a new value\".to_string(),"] #[doc = "     ..thing"] #[doc = " };"] #[doc = " ```"] #[doc = ""] #[doc = " Tuple structs are instantiated in the same way as tuples themselves, except with the struct's"] #[doc = " name as a prefix: `Foo(123, false, 0.1)`."] #[doc = ""] #[doc = " Empty structs are instantiated with just their name, and don't need anything else. `let thing ="] #[doc = " EmptyStruct;`"] #[doc = ""] #[doc = " # Style conventions"] #[doc = ""] #[doc = " Structs are always written in UpperCamelCase, with few exceptions. While the trailing comma on a"] #[doc = " struct's list of fields can be omitted, it's usually kept for convenience in adding and"] #[doc = " removing fields down the line."] #[doc = ""] #[doc = " For more information on structs, take a look at the [Rust Book][book] or the"] #[doc = " [Reference][reference]."] #[doc = ""] #[doc = " [`PhantomData`]: marker::PhantomData"] #[doc = " [book]: ../book/ch05-01-defining-structs.html"] #[doc = " [reference]: ../reference/items/structs.html"] mod struct_keyword { } #[doc (keyword = "super")] #[doc = " The parent of the current [module]."] #[doc = ""] #[doc = " ```rust"] #[doc = " # #![allow(dead_code)]"] #[doc = " # fn main() {}"] #[doc = " mod a {"] #[doc = "     pub fn foo() {}"] #[doc = " }"] #[doc = " mod b {"] #[doc = "     pub fn foo() {"] #[doc = "         super::a::foo(); // call a's foo function"] #[doc = "     }"] #[doc = " }"] #[doc = " ```"] #[doc = ""] #[doc = " It is also possible to use `super` multiple times: `super::super::foo`,"] #[doc = " going up the ancestor chain."] #[doc = ""] #[doc = " See the [Reference] for more information."] #[doc = ""] #[doc = " [module]: ../reference/items/modules.html"] #[doc = " [Reference]: ../reference/paths.html#super"] mod super_keyword { } #[doc (keyword = "trait")] #[doc = " A common interface for a group of types."] #[doc = ""] #[doc = " A `trait` is like an interface that data types can implement. When a type"] #[doc = " implements a trait it can be treated abstractly as that trait using generics"] #[doc = " or trait objects."] #[doc = ""] #[doc = " Traits can be made up of three varieties of associated items:"] #[doc = ""] #[doc = " - functions and methods"] #[doc = " - types"] #[doc = " - constants"] #[doc = ""] #[doc = " Traits may also contain additional type parameters. Those type parameters"] #[doc = " or the trait itself can be constrained by other traits."] #[doc = ""] #[doc = " Traits can serve as markers or carry other logical semantics that"] #[doc = " aren't expressed through their items. When a type implements that"] #[doc = " trait it is promising to uphold its contract. [`Send`] and [`Sync`] are two"] #[doc = " such marker traits present in the standard library."] #[doc = ""] #[doc = " See the [Reference][Ref-Traits] for a lot more information on traits."] #[doc = ""] #[doc = " # Examples"] #[doc = ""] #[doc = " Traits are declared using the `trait` keyword. Types can implement them"] #[doc = " using [`impl`] `Trait` [`for`] `Type`:"] #[doc = ""] #[doc = " ```rust"] #[doc = " trait Zero {"] #[doc = "     const ZERO: Self;"] #[doc = "     fn is_zero(&self) -> bool;"] #[doc = " }"] #[doc = ""] #[doc = " impl Zero for i32 {"] #[doc = "     const ZERO: Self = 0;"] #[doc = ""] #[doc = "     fn is_zero(&self) -> bool {"] #[doc = "         *self == Self::ZERO"] #[doc = "     }"] #[doc = " }"] #[doc = ""] #[doc = " assert_eq!(i32::ZERO, 0);"] #[doc = " assert!(i32::ZERO.is_zero());"] #[doc = " assert!(!4.is_zero());"] #[doc = " ```"] #[doc = ""] #[doc = " With an associated type:"] #[doc = ""] #[doc = " ```rust"] #[doc = " trait Builder {"] #[doc = "     type Built;"] #[doc = ""] #[doc = "     fn build(&self) -> Self::Built;"] #[doc = " }"] #[doc = " ```"] #[doc = ""] #[doc = " Traits can be generic, with constraints or without:"] #[doc = ""] #[doc = " ```rust"] #[doc = " trait MaybeFrom<T> {"] #[doc = "     fn maybe_from(value: T) -> Option<Self>"] #[doc = "     where"] #[doc = "         Self: Sized;"] #[doc = " }"] #[doc = " ```"] #[doc = ""] #[doc = " Traits can build upon the requirements of other traits. In the example"] #[doc = " below `Iterator` is a **supertrait** and `ThreeIterator` is a **subtrait**:"] #[doc = ""] #[doc = " ```rust"] #[doc = " trait ThreeIterator: Iterator {"] #[doc = "     fn next_three(&mut self) -> Option<[Self::Item; 3]>;"] #[doc = " }"] #[doc = " ```"] #[doc = ""] #[doc = " Traits can be used in functions, as parameters:"] #[doc = ""] #[doc = " ```rust"] #[doc = " # #![allow(dead_code)]"] #[doc = " fn debug_iter<I: Iterator>(it: I) where I::Item: std::fmt::Debug {"] #[doc = "     for elem in it {"] #[doc = "         println!(\"{elem:#?}\");"] #[doc = "     }"] #[doc = " }"] #[doc = ""] #[doc = " // u8_len_1, u8_len_2 and u8_len_3 are equivalent"] #[doc = ""] #[doc = " fn u8_len_1(val: impl Into<Vec<u8>>) -> usize {"] #[doc = "     val.into().len()"] #[doc = " }"] #[doc = ""] #[doc = " fn u8_len_2<T: Into<Vec<u8>>>(val: T) -> usize {"] #[doc = "     val.into().len()"] #[doc = " }"] #[doc = ""] #[doc = " fn u8_len_3<T>(val: T) -> usize"] #[doc = " where"] #[doc = "     T: Into<Vec<u8>>,"] #[doc = " {"] #[doc = "     val.into().len()"] #[doc = " }"] #[doc = " ```"] #[doc = ""] #[doc = " Or as return types:"] #[doc = ""] #[doc = " ```rust"] #[doc = " # #![allow(dead_code)]"] #[doc = " fn from_zero_to(v: u8) -> impl Iterator<Item = u8> {"] #[doc = "     (0..v).into_iter()"] #[doc = " }"] #[doc = " ```"] #[doc = ""] #[doc = " The use of the [`impl`] keyword in this position allows the function writer"] #[doc = " to hide the concrete type as an implementation detail which can change"] #[doc = " without breaking user's code."] #[doc = ""] #[doc = " # Trait objects"] #[doc = ""] #[doc = " A *trait object* is an opaque value of another type that implements a set of"] #[doc = " traits. A trait object implements all specified traits as well as their"] #[doc = " supertraits (if any)."] #[doc = ""] #[doc = " The syntax is the following: `dyn BaseTrait + AutoTrait1 + ... AutoTraitN`."] #[doc = " Only one `BaseTrait` can be used so this will not compile:"] #[doc = ""] #[doc = " ```rust,compile_fail,E0225"] #[doc = " trait A {}"] #[doc = " trait B {}"] #[doc = ""] #[doc = " let _: Box<dyn A + B>;"] #[doc = " ```"] #[doc = ""] #[doc = " Neither will this, which is a syntax error:"] #[doc = ""] #[doc = " ```rust,compile_fail"] #[doc = " trait A {}"] #[doc = " trait B {}"] #[doc = ""] #[doc = " let _: Box<dyn A + dyn B>;"] #[doc = " ```"] #[doc = ""] #[doc = " On the other hand, this is correct:"] #[doc = ""] #[doc = " ```rust"] #[doc = " trait A {}"] #[doc = ""] #[doc = " let _: Box<dyn A + Send + Sync>;"] #[doc = " ```"] #[doc = ""] #[doc = " The [Reference][Ref-Trait-Objects] has more information about trait objects,"] #[doc = " their limitations and the differences between editions."] #[doc = ""] #[doc = " # Unsafe traits"] #[doc = ""] #[doc = " Some traits may be unsafe to implement. Using the [`unsafe`] keyword in"] #[doc = " front of the trait's declaration is used to mark this:"] #[doc = ""] #[doc = " ```rust"] #[doc = " unsafe trait UnsafeTrait {}"] #[doc = ""] #[doc = " unsafe impl UnsafeTrait for i32 {}"] #[doc = " ```"] #[doc = ""] #[doc = " # Differences between the 2015 and 2018 editions"] #[doc = ""] #[doc = " In the 2015 edition the parameters pattern was not needed for traits:"] #[doc = ""] #[doc = " ```rust,edition2015"] #[doc = " # #![allow(anonymous_parameters)]"] #[doc = " trait Tr {"] #[doc = "     fn f(i32);"] #[doc = " }"] #[doc = " ```"] #[doc = ""] #[doc = " This behavior is no longer valid in edition 2018."] #[doc = ""] #[doc = " [`for`]: keyword.for.html"] #[doc = " [`impl`]: keyword.impl.html"] #[doc = " [`unsafe`]: keyword.unsafe.html"] #[doc = " [Ref-Traits]: ../reference/items/traits.html"] #[doc = " [Ref-Trait-Objects]: ../reference/types/trait-object.html"] mod trait_keyword { } #[doc (keyword = "true")] #[doc = " A value of type [`bool`] representing logical **true**."] #[doc = ""] #[doc = " Logically `true` is not equal to [`false`]."] #[doc = ""] #[doc = " ## Control structures that check for **true**"] #[doc = ""] #[doc = " Several of Rust's control structures will check for a `bool` condition evaluating to **true**."] #[doc = ""] #[doc = "   * The condition in an [`if`] expression must be of type `bool`."] #[doc = "     Whenever that condition evaluates to **true**, the `if` expression takes"] #[doc = "     on the value of the first block. If however, the condition evaluates"] #[doc = "     to `false`, the expression takes on value of the `else` block if there is one."] #[doc = ""] #[doc = "   * [`while`] is another control flow construct expecting a `bool`-typed condition."] #[doc = "     As long as the condition evaluates to **true**, the `while` loop will continually"] #[doc = "     evaluate its associated block."] #[doc = ""] #[doc = "   * [`match`] arms can have guard clauses on them."] #[doc = ""] #[doc = " [`if`]: keyword.if.html"] #[doc = " [`while`]: keyword.while.html"] #[doc = " [`match`]: ../reference/expressions/match-expr.html#match-guards"] #[doc = " [`false`]: keyword.false.html"] mod true_keyword { } #[doc (keyword = "type")] #[doc = " Define an [alias] for an existing type."] #[doc = ""] #[doc = " The syntax is `type Name = ExistingType;`."] #[doc = ""] #[doc = " # Examples"] #[doc = ""] #[doc = " `type` does **not** create a new type:"] #[doc = ""] #[doc = " ```rust"] #[doc = " type Meters = u32;"] #[doc = " type Kilograms = u32;"] #[doc = ""] #[doc = " let m: Meters = 3;"] #[doc = " let k: Kilograms = 3;"] #[doc = ""] #[doc = " assert_eq!(m, k);"] #[doc = " ```"] #[doc = ""] #[doc = " A type can be generic:"] #[doc = ""] #[doc = " ```rust"] #[doc = " # use std::sync::{Arc, Mutex};"] #[doc = " type ArcMutex<T> = Arc<Mutex<T>>;"] #[doc = " ```"] #[doc = ""] #[doc = " In traits, `type` is used to declare an [associated type]:"] #[doc = ""] #[doc = " ```rust"] #[doc = " trait Iterator {"] #[doc = "     // associated type declaration"] #[doc = "     type Item;"] #[doc = "     fn next(&mut self) -> Option<Self::Item>;"] #[doc = " }"] #[doc = ""] #[doc = " struct Once<T>(Option<T>);"] #[doc = ""] #[doc = " impl<T> Iterator for Once<T> {"] #[doc = "     // associated type definition"] #[doc = "     type Item = T;"] #[doc = "     fn next(&mut self) -> Option<Self::Item> {"] #[doc = "         self.0.take()"] #[doc = "     }"] #[doc = " }"] #[doc = " ```"] #[doc = ""] #[doc = " [`trait`]: keyword.trait.html"] #[doc = " [associated type]: ../reference/items/associated-items.html#associated-types"] #[doc = " [alias]: ../reference/items/type-aliases.html"] mod type_keyword { } #[doc (keyword = "unsafe")] #[doc = " Code or interfaces whose [memory safety] cannot be verified by the type"] #[doc = " system."] #[doc = ""] #[doc = " The `unsafe` keyword has two uses:"] #[doc = " - to declare the existence of contracts the compiler can't check (`unsafe fn` and `unsafe"] #[doc = " trait`),"] #[doc = " - and to declare that a programmer has checked that these contracts have been upheld (`unsafe"] #[doc = " {}` and `unsafe impl`, but also `unsafe fn` -- see below)."] #[doc = ""] #[doc = " # Unsafe abilities"] #[doc = ""] #[doc = " **No matter what, Safe Rust can't cause Undefined Behavior**. This is"] #[doc = " referred to as [soundness]: a well-typed program actually has the desired"] #[doc = " properties. The [Nomicon][nomicon-soundness] has a more detailed explanation"] #[doc = " on the subject."] #[doc = ""] #[doc = " To ensure soundness, Safe Rust is restricted enough that it can be"] #[doc = " automatically checked. Sometimes, however, it is necessary to write code"] #[doc = " that is correct for reasons which are too clever for the compiler to"] #[doc = " understand. In those cases, you need to use Unsafe Rust."] #[doc = ""] #[doc = " Here are the abilities Unsafe Rust has in addition to Safe Rust:"] #[doc = ""] #[doc = " - Dereference [raw pointers]"] #[doc = " - Implement `unsafe` [`trait`]s"] #[doc = " - Call `unsafe` functions"] #[doc = " - Mutate [`static`]s (including [`extern`]al ones)"] #[doc = " - Access fields of [`union`]s"] #[doc = ""] #[doc = " However, this extra power comes with extra responsibilities: it is now up to"] #[doc = " you to ensure soundness. The `unsafe` keyword helps by clearly marking the"] #[doc = " pieces of code that need to worry about this."] #[doc = ""] #[doc = " ## The different meanings of `unsafe`"] #[doc = ""] #[doc = " Not all uses of `unsafe` are equivalent: some are here to mark the existence"] #[doc = " of a contract the programmer must check, others are to say \"I have checked"] #[doc = " the contract, go ahead and do this\". The following"] #[doc = " [discussion on Rust Internals] has more in-depth explanations about this but"] #[doc = " here is a summary of the main points:"] #[doc = ""] #[doc = " - `unsafe fn`: calling this function means abiding by a contract the"] #[doc = " compiler cannot enforce."] #[doc = " - `unsafe trait`: implementing the [`trait`] means abiding by a"] #[doc = " contract the compiler cannot enforce."] #[doc = " - `unsafe {}`: the contract necessary to call the operations inside the"] #[doc = " block has been checked by the programmer and is guaranteed to be respected."] #[doc = " - `unsafe impl`: the contract necessary to implement the trait has been"] #[doc = " checked by the programmer and is guaranteed to be respected."] #[doc = ""] #[doc = " See the [Rustonomicon] and the [Reference] for more information."] #[doc = ""] #[doc = " # Examples"] #[doc = ""] #[doc = " ## Marking elements as `unsafe`"] #[doc = ""] #[doc = " `unsafe` can be used on functions. Note that functions and statics declared"] #[doc = " in [`extern`] blocks are implicitly marked as `unsafe` (but not functions"] #[doc = " declared as `extern \"something\" fn ...`). Mutable statics are always unsafe,"] #[doc = " wherever they are declared. Methods can also be declared as `unsafe`:"] #[doc = ""] #[doc = " ```rust"] #[doc = " # #![allow(dead_code)]"] #[doc = " static mut FOO: &str = \"hello\";"] #[doc = ""] #[doc = " unsafe fn unsafe_fn() {}"] #[doc = ""] #[doc = " unsafe extern \"C\" {"] #[doc = "     fn unsafe_extern_fn();"] #[doc = "     static BAR: *mut u32;"] #[doc = " }"] #[doc = ""] #[doc = " trait SafeTraitWithUnsafeMethod {"] #[doc = "     unsafe fn unsafe_method(&self);"] #[doc = " }"] #[doc = ""] #[doc = " struct S;"] #[doc = ""] #[doc = " impl S {"] #[doc = "     unsafe fn unsafe_method_on_struct() {}"] #[doc = " }"] #[doc = " ```"] #[doc = ""] #[doc = " Traits can also be declared as `unsafe`:"] #[doc = ""] #[doc = " ```rust"] #[doc = " unsafe trait UnsafeTrait {}"] #[doc = " ```"] #[doc = ""] #[doc = " Since `unsafe fn` and `unsafe trait` indicate that there is a safety"] #[doc = " contract that the compiler cannot enforce, documenting it is important. The"] #[doc = " standard library has many examples of this, like the following which is an"] #[doc = " extract from [`Vec::set_len`]. The `# Safety` section explains the contract"] #[doc = " that must be fulfilled to safely call the function."] #[doc = ""] #[doc = " ```rust,ignore (stub-to-show-doc-example)"] #[doc = " /// Forces the length of the vector to `new_len`."] #[doc = " ///"] #[doc = " /// This is a low-level operation that maintains none of the normal"] #[doc = " /// invariants of the type. Normally changing the length of a vector"] #[doc = " /// is done using one of the safe operations instead, such as"] #[doc = " /// `truncate`, `resize`, `extend`, or `clear`."] #[doc = " ///"] #[doc = " /// # Safety"] #[doc = " ///"] #[doc = " /// - `new_len` must be less than or equal to `capacity()`."] #[doc = " /// - The elements at `old_len..new_len` must be initialized."] #[doc = " pub unsafe fn set_len(&mut self, new_len: usize)"] #[doc = " ```"] #[doc = ""] #[doc = " ## Using `unsafe {}` blocks and `impl`s"] #[doc = ""] #[doc = " Performing `unsafe` operations requires an `unsafe {}` block:"] #[doc = ""] #[doc = " ```rust"] #[doc = " # #![allow(dead_code)]"] #[doc = " #![deny(unsafe_op_in_unsafe_fn)]"] #[doc = ""] #[doc = " /// Dereference the given pointer."] #[doc = " ///"] #[doc = " /// # Safety"] #[doc = " ///"] #[doc = " /// `ptr` must be aligned and must not be dangling."] #[doc = " unsafe fn deref_unchecked(ptr: *const i32) -> i32 {"] #[doc = "     // SAFETY: the caller is required to ensure that `ptr` is aligned and dereferenceable."] #[doc = "     unsafe { *ptr }"] #[doc = " }"] #[doc = ""] #[doc = " let a = 3;"] #[doc = " let b = &a as *const _;"] #[doc = " // SAFETY: `a` has not been dropped and references are always aligned,"] #[doc = " // so `b` is a valid address."] #[doc = " unsafe { assert_eq!(*b, deref_unchecked(b)); };"] #[doc = " ```"] #[doc = ""] #[doc = " ## `unsafe` and traits"] #[doc = ""] #[doc = " The interactions of `unsafe` and traits can be surprising, so let us contrast the"] #[doc = " two combinations of safe `fn` in `unsafe trait` and `unsafe fn` in safe trait using two"] #[doc = " examples:"] #[doc = ""] #[doc = " ```rust"] #[doc = " /// # Safety"] #[doc = " ///"] #[doc = " /// `make_even` must return an even number."] #[doc = " unsafe trait MakeEven {"] #[doc = "     fn make_even(&self) -> i32;"] #[doc = " }"] #[doc = ""] #[doc = " // SAFETY: Our `make_even` always returns something even."] #[doc = " unsafe impl MakeEven for i32 {"] #[doc = "     fn make_even(&self) -> i32 {"] #[doc = "         self << 1"] #[doc = "     }"] #[doc = " }"] #[doc = ""] #[doc = " fn use_make_even(x: impl MakeEven) {"] #[doc = "     if x.make_even() % 2 == 1 {"] #[doc = "         // SAFETY: this can never happen, because all `MakeEven` implementations"] #[doc = "         // ensure that `make_even` returns something even."] #[doc = "         unsafe { std::hint::unreachable_unchecked() };"] #[doc = "     }"] #[doc = " }"] #[doc = " ```"] #[doc = ""] #[doc = " Note how the safety contract of the trait is upheld by the implementation, and is itself used to"] #[doc = " uphold the safety contract of the unsafe function `unreachable_unchecked` called by"] #[doc = " `use_make_even`. `make_even` itself is a safe function because its *callers* do not have to"] #[doc = " worry about any contract, only the *implementation* of `MakeEven` is required to uphold a"] #[doc = " certain contract. `use_make_even` is safe because it can use the promise made by `MakeEven`"] #[doc = " implementations to uphold the safety contract of the `unsafe fn unreachable_unchecked` it calls."] #[doc = ""] #[doc = " It is also possible to have `unsafe fn` in a regular safe `trait`:"] #[doc = ""] #[doc = " ```rust"] #[doc = " # #![feature(never_type)]"] #[doc = " #![deny(unsafe_op_in_unsafe_fn)]"] #[doc = ""] #[doc = " trait Indexable {"] #[doc = "     const LEN: usize;"] #[doc = ""] #[doc = "     /// # Safety"] #[doc = "     ///"] #[doc = "     /// The caller must ensure that `idx < LEN`."] #[doc = "     unsafe fn idx_unchecked(&self, idx: usize) -> i32;"] #[doc = " }"] #[doc = ""] #[doc = " // The implementation for `i32` doesn't need to do any contract reasoning."] #[doc = " impl Indexable for i32 {"] #[doc = "     const LEN: usize = 1;"] #[doc = ""] #[doc = "     /// See `Indexable` for the safety contract."] #[doc = "     unsafe fn idx_unchecked(&self, idx: usize) -> i32 {"] #[doc = "         debug_assert_eq!(idx, 0);"] #[doc = "         *self"] #[doc = "     }"] #[doc = " }"] #[doc = ""] #[doc = " // The implementation for arrays exploits the function contract to"] #[doc = " // make use of `get_unchecked` on slices and avoid a run-time check."] #[doc = " impl Indexable for [i32; 42] {"] #[doc = "     const LEN: usize = 42;"] #[doc = ""] #[doc = "     /// See `Indexable` for the safety contract."] #[doc = "     unsafe fn idx_unchecked(&self, idx: usize) -> i32 {"] #[doc = "         // SAFETY: As per this trait's documentation, the caller ensures"] #[doc = "         // that `idx < 42`."] #[doc = "         unsafe { *self.get_unchecked(idx) }"] #[doc = "     }"] #[doc = " }"] #[doc = ""] #[doc = " // The implementation for the never type declares a length of 0,"] #[doc = " // which means `idx_unchecked` can never be called."] #[doc = " impl Indexable for ! {"] #[doc = "     const LEN: usize = 0;"] #[doc = ""] #[doc = "     /// See `Indexable` for the safety contract."] #[doc = "     unsafe fn idx_unchecked(&self, idx: usize) -> i32 {"] #[doc = "         // SAFETY: As per this trait's documentation, the caller ensures"] #[doc = "         // that `idx < 0`, which is impossible, so this is dead code."] #[doc = "         unsafe { std::hint::unreachable_unchecked() }"] #[doc = "     }"] #[doc = " }"] #[doc = ""] #[doc = " fn use_indexable<I: Indexable>(x: I, idx: usize) -> i32 {"] #[doc = "     if idx < I::LEN {"] #[doc = "         // SAFETY: We have checked that `idx < I::LEN`."] #[doc = "         unsafe { x.idx_unchecked(idx) }"] #[doc = "     } else {"] #[doc = "         panic!(\"index out-of-bounds\")"] #[doc = "     }"] #[doc = " }"] #[doc = " ```"] #[doc = ""] #[doc = " This time, `use_indexable` is safe because it uses a run-time check to discharge the safety"] #[doc = " contract of `idx_unchecked`. Implementing `Indexable` is safe because when writing"] #[doc = " `idx_unchecked`, we don't have to worry: our *callers* need to discharge a proof obligation"] #[doc = " (like `use_indexable` does), but the *implementation* of `get_unchecked` has no proof obligation"] #[doc = " to contend with. Of course, the implementation may choose to call other unsafe operations, and"] #[doc = " then it needs an `unsafe` *block* to indicate it discharged the proof obligations of its"] #[doc = " callees. For that purpose it can make use of the contract that all its callers must uphold --"] #[doc = " the fact that `idx < LEN`."] #[doc = ""] #[doc = " Note that unlike normal `unsafe fn`, an `unsafe fn` in a trait implementation does not get to"] #[doc = " just pick an arbitrary safety contract! It *has* to use the safety contract defined by the trait"] #[doc = " (or one with weaker preconditions)."] #[doc = ""] #[doc = " Formally speaking, an `unsafe fn` in a trait is a function with *preconditions* that go beyond"] #[doc = " those encoded by the argument types (such as `idx < LEN`), whereas an `unsafe trait` can declare"] #[doc = " that some of its functions have *postconditions* that go beyond those encoded in the return type"] #[doc = " (such as returning an even integer). If a trait needs a function with both extra precondition"] #[doc = " and extra postcondition, then it needs an `unsafe fn` in an `unsafe trait`."] #[doc = ""] #[doc = " [`extern`]: keyword.extern.html"] #[doc = " [`trait`]: keyword.trait.html"] #[doc = " [`static`]: keyword.static.html"] #[doc = " [`union`]: keyword.union.html"] #[doc = " [`impl`]: keyword.impl.html"] #[doc = " [raw pointers]: ../reference/types/pointer.html"] #[doc = " [memory safety]: ../book/ch19-01-unsafe-rust.html"] #[doc = " [Rustonomicon]: ../nomicon/index.html"] #[doc = " [nomicon-soundness]: ../nomicon/safe-unsafe-meaning.html"] #[doc = " [soundness]: https://rust-lang.github.io/unsafe-code-guidelines/glossary.html#soundness-of-code--of-a-library"] #[doc = " [Reference]: ../reference/unsafety.html"] #[doc = " [discussion on Rust Internals]: https://internals.rust-lang.org/t/what-does-unsafe-mean/6696"] mod unsafe_keyword { } #[doc (keyword = "use")] #[doc = " Import or rename items from other crates or modules, use values under ergonomic clones"] #[doc = " semantic, or specify precise capturing with `use<..>`."] #[doc = ""] #[doc = " ## Importing items"] #[doc = ""] #[doc = " The `use` keyword is employed to shorten the path required to refer to a module item."] #[doc = " The keyword may appear in modules, blocks, and even functions, typically at the top."] #[doc = ""] #[doc = " The most basic usage of the keyword is `use path::to::item;`,"] #[doc = " though a number of convenient shortcuts are supported:"] #[doc = ""] #[doc = "   * Simultaneously binding a list of paths with a common prefix,"] #[doc = "     using the glob-like brace syntax `use a::b::{c, d, e::f, g::h::i};`"] #[doc = "   * Simultaneously binding a list of paths with a common prefix and their common parent module,"] #[doc = "     using the [`self`] keyword, such as `use a::b::{self, c, d::e};`"] #[doc = "   * Rebinding the target name as a new local name, using the syntax `use p::q::r as x;`."] #[doc = "     This can also be used with the last two features: `use a::b::{self as ab, c as abc}`."] #[doc = "   * Binding all paths matching a given prefix,"] #[doc = "     using the asterisk wildcard syntax `use a::b::*;`."] #[doc = "   * Nesting groups of the previous features multiple times,"] #[doc = "     such as `use a::b::{self as ab, c, d::{*, e::f}};`"] #[doc = "   * Reexporting with visibility modifiers such as `pub use a::b;`"] #[doc = "   * Importing with `_` to only import the methods of a trait without binding it to a name"] #[doc = "     (to avoid conflict for example): `use ::std::io::Read as _;`."] #[doc = ""] #[doc = " Using path qualifiers like [`crate`], [`super`] or [`self`] is supported: `use crate::a::b;`."] #[doc = ""] #[doc = " Note that when the wildcard `*` is used on a type, it does not import its methods (though"] #[doc = " for `enum`s it imports the variants, as shown in the example below)."] #[doc = ""] #[doc = " ```compile_fail,edition2018"] #[doc = " enum ExampleEnum {"] #[doc = "     VariantA,"] #[doc = "     VariantB,"] #[doc = " }"] #[doc = ""] #[doc = " impl ExampleEnum {"] #[doc = "     fn new() -> Self {"] #[doc = "         Self::VariantA"] #[doc = "     }"] #[doc = " }"] #[doc = ""] #[doc = " use ExampleEnum::*;"] #[doc = ""] #[doc = " // Compiles."] #[doc = " let _ = VariantA;"] #[doc = ""] #[doc = " // Does not compile!"] #[doc = " let n = new();"] #[doc = " ```"] #[doc = ""] #[doc = " For more information on `use` and paths in general, see the [Reference][ref-use-decls]."] #[doc = ""] #[doc = " The differences about paths and the `use` keyword between the 2015 and 2018 editions"] #[doc = " can also be found in the [Reference][ref-use-decls]."] #[doc = ""] #[doc = " ## Precise capturing"] #[doc = ""] #[doc = " The `use<..>` syntax is used within certain `impl Trait` bounds to control which generic"] #[doc = " parameters are captured. This is important for return-position `impl Trait` (RPIT) types,"] #[doc = " as it affects borrow checking by controlling which generic parameters can be used in the"] #[doc = " hidden type."] #[doc = ""] #[doc = " For example, the following function demonstrates an error without precise capturing in"] #[doc = " Rust 2021 and earlier editions:"] #[doc = ""] #[doc = " ```rust,compile_fail,edition2021"] #[doc = " fn f(x: &()) -> impl Sized { x }"] #[doc = " ```"] #[doc = ""] #[doc = " By using `use<'_>` for precise capturing, it can be resolved:"] #[doc = ""] #[doc = " ```rust"] #[doc = " fn f(x: &()) -> impl Sized + use<'_> { x }"] #[doc = " ```"] #[doc = ""] #[doc = " This syntax specifies that the elided lifetime be captured and therefore available for"] #[doc = " use in the hidden type."] #[doc = ""] #[doc = " In Rust 2024, opaque types automatically capture all lifetime parameters in scope."] #[doc = " `use<..>` syntax serves as an important way of opting-out of that default."] #[doc = ""] #[doc = " For more details about precise capturing, see the [Reference][ref-impl-trait]."] #[doc = ""] #[doc = " ## Ergonomic clones"] #[doc = ""] #[doc = " Use a values, copying its content if the value implements `Copy`, cloning the contents if the"] #[doc = " value implements `UseCloned` or moving it otherwise."] #[doc = ""] #[doc = " [`crate`]: keyword.crate.html"] #[doc = " [`self`]: keyword.self.html"] #[doc = " [`super`]: keyword.super.html"] #[doc = " [ref-use-decls]: ../reference/items/use-declarations.html"] #[doc = " [ref-impl-trait]: ../reference/types/impl-trait.html"] mod use_keyword { } #[doc (keyword = "where")] #[doc = " Add constraints that must be upheld to use an item."] #[doc = ""] #[doc = " `where` allows specifying constraints on lifetime and generic parameters."] #[doc = " The [RFC] introducing `where` contains detailed information about the"] #[doc = " keyword."] #[doc = ""] #[doc = " # Examples"] #[doc = ""] #[doc = " `where` can be used for constraints with traits:"] #[doc = ""] #[doc = " ```rust"] #[doc = " fn new<T: Default>() -> T {"] #[doc = "     T::default()"] #[doc = " }"] #[doc = ""] #[doc = " fn new_where<T>() -> T"] #[doc = " where"] #[doc = "     T: Default,"] #[doc = " {"] #[doc = "     T::default()"] #[doc = " }"] #[doc = ""] #[doc = " assert_eq!(0.0, new());"] #[doc = " assert_eq!(0.0, new_where());"] #[doc = ""] #[doc = " assert_eq!(0, new());"] #[doc = " assert_eq!(0, new_where());"] #[doc = " ```"] #[doc = ""] #[doc = " `where` can also be used for lifetimes."] #[doc = ""] #[doc = " This compiles because `longer` outlives `shorter`, thus the constraint is"] #[doc = " respected:"] #[doc = ""] #[doc = " ```rust"] #[doc = " fn select<'short, 'long>(s1: &'short str, s2: &'long str, second: bool) -> &'short str"] #[doc = " where"] #[doc = "     'long: 'short,"] #[doc = " {"] #[doc = "     if second { s2 } else { s1 }"] #[doc = " }"] #[doc = ""] #[doc = " let outer = String::from(\"Long living ref\");"] #[doc = " let longer = &outer;"] #[doc = " {"] #[doc = "     let inner = String::from(\"Short living ref\");"] #[doc = "     let shorter = &inner;"] #[doc = ""] #[doc = "     assert_eq!(select(shorter, longer, false), shorter);"] #[doc = "     assert_eq!(select(shorter, longer, true), longer);"] #[doc = " }"] #[doc = " ```"] #[doc = ""] #[doc = " On the other hand, this will not compile because the `where 'b: 'a` clause"] #[doc = " is missing: the `'b` lifetime is not known to live at least as long as `'a`"] #[doc = " which means this function cannot ensure it always returns a valid reference:"] #[doc = ""] #[doc = " ```rust,compile_fail"] #[doc = " fn select<'a, 'b>(s1: &'a str, s2: &'b str, second: bool) -> &'a str"] #[doc = " {"] #[doc = "     if second { s2 } else { s1 }"] #[doc = " }"] #[doc = " ```"] #[doc = ""] #[doc = " `where` can also be used to express more complicated constraints that cannot"] #[doc = " be written with the `<T: Trait>` syntax:"] #[doc = ""] #[doc = " ```rust"] #[doc = " fn first_or_default<I>(mut i: I) -> I::Item"] #[doc = " where"] #[doc = "     I: Iterator,"] #[doc = "     I::Item: Default,"] #[doc = " {"] #[doc = "     i.next().unwrap_or_else(I::Item::default)"] #[doc = " }"] #[doc = ""] #[doc = " assert_eq!(first_or_default([1, 2, 3].into_iter()), 1);"] #[doc = " assert_eq!(first_or_default(Vec::<i32>::new().into_iter()), 0);"] #[doc = " ```"] #[doc = ""] #[doc = " `where` is available anywhere generic and lifetime parameters are available,"] #[doc = " as can be seen with the [`Cow`](crate::borrow::Cow) type from the standard"] #[doc = " library:"] #[doc = ""] #[doc = " ```rust"] #[doc = " # #![allow(dead_code)]"] #[doc = " pub enum Cow<'a, B>"] #[doc = " where"] #[doc = "     B: ToOwned + ?Sized,"] #[doc = " {"] #[doc = "     Borrowed(&'a B),"] #[doc = "     Owned(<B as ToOwned>::Owned),"] #[doc = " }"] #[doc = " ```"] #[doc = ""] #[doc = " [RFC]: https://github.com/rust-lang/rfcs/blob/master/text/0135-where.md"] mod where_keyword { } #[doc (keyword = "while")] #[doc = " Loop while a condition is upheld."] #[doc = ""] #[doc = " A `while` expression is used for predicate loops. The `while` expression runs the conditional"] #[doc = " expression before running the loop body, then runs the loop body if the conditional"] #[doc = " expression evaluates to `true`, or exits the loop otherwise."] #[doc = ""] #[doc = " ```rust"] #[doc = " let mut counter = 0;"] #[doc = ""] #[doc = " while counter < 10 {"] #[doc = "     println!(\"{counter}\");"] #[doc = "     counter += 1;"] #[doc = " }"] #[doc = " ```"] #[doc = ""] #[doc = " Like the [`for`] expression, we can use `break` and `continue`. A `while` expression"] #[doc = " cannot break with a value and always evaluates to `()` unlike [`loop`]."] #[doc = ""] #[doc = " ```rust"] #[doc = " let mut i = 1;"] #[doc = ""] #[doc = " while i < 100 {"] #[doc = "     i *= 2;"] #[doc = "     if i == 64 {"] #[doc = "         break; // Exit when `i` is 64."] #[doc = "     }"] #[doc = " }"] #[doc = " ```"] #[doc = ""] #[doc = " As `if` expressions have their pattern matching variant in `if let`, so too do `while`"] #[doc = " expressions with `while let`. The `while let` expression matches the pattern against the"] #[doc = " expression, then runs the loop body if pattern matching succeeds, or exits the loop otherwise."] #[doc = " We can use `break` and `continue` in `while let` expressions just like in `while`."] #[doc = ""] #[doc = " ```rust"] #[doc = " let mut counter = Some(0);"] #[doc = ""] #[doc = " while let Some(i) = counter {"] #[doc = "     if i == 10 {"] #[doc = "         counter = None;"] #[doc = "     } else {"] #[doc = "         println!(\"{i}\");"] #[doc = "         counter = Some (i + 1);"] #[doc = "     }"] #[doc = " }"] #[doc = " ```"] #[doc = ""] #[doc = " For more information on `while` and loops in general, see the [reference]."] #[doc = ""] #[doc = " See also, [`for`], [`loop`]."] #[doc = ""] #[doc = " [`for`]: keyword.for.html"] #[doc = " [`loop`]: keyword.loop.html"] #[doc = " [reference]: ../reference/expressions/loop-expr.html#predicate-loops"] mod while_keyword { } #[doc (alias = "promise")] #[doc (keyword = "async")] #[doc = " Returns a [`Future`] instead of blocking the current thread."] #[doc = ""] #[doc = " Use `async` in front of `fn`, `closure`, or a `block` to turn the marked code into a `Future`."] #[doc = " As such the code will not be run immediately, but will only be evaluated when the returned"] #[doc = " future is [`.await`]ed."] #[doc = ""] #[doc = " We have written an [async book] detailing `async`/`await` and trade-offs compared to using threads."] #[doc = ""] #[doc = " ## Control Flow"] #[doc = " [`return`] statements and [`?`][try operator] operators within `async` blocks do not cause"] #[doc = " a return from the parent function; rather, they cause the `Future` returned by the block to"] #[doc = " return with that value."] #[doc = ""] #[doc = " For example, the following Rust function will return `5`, causing `x` to take the [`!` type][never type]:"] #[doc = " ```rust"] #[doc = " #[expect(unused_variables)]"] #[doc = " fn example() -> i32 {"] #[doc = "     let x = {"] #[doc = "         return 5;"] #[doc = "     };"] #[doc = " }"] #[doc = " ```"] #[doc = " In contrast, the following asynchronous function assigns a `Future<Output = i32>` to `x`, and"] #[doc = " only returns `5` when `x` is `.await`ed:"] #[doc = " ```rust"] #[doc = " async fn example() -> i32 {"] #[doc = "     let x = async {"] #[doc = "         return 5;"] #[doc = "     };"] #[doc = ""] #[doc = "     x.await"] #[doc = " }"] #[doc = " ```"] #[doc = " Code using `?` behaves similarly - it causes the `async` block to return a [`Result`] without"] #[doc = " affecting the parent function."] #[doc = ""] #[doc = " Note that you cannot use `break` or `continue` from within an `async` block to affect the"] #[doc = " control flow of a loop in the parent function."] #[doc = ""] #[doc = " Control flow in `async` blocks is documented further in the [async book][async book blocks]."] #[doc = ""] #[doc = " ## Editions"] #[doc = ""] #[doc = " `async` is a keyword from the 2018 edition onwards."] #[doc = ""] #[doc = " It is available for use in stable Rust from version 1.39 onwards."] #[doc = ""] #[doc = " [`Future`]: future::Future"] #[doc = " [`.await`]: ../std/keyword.await.html"] #[doc = " [async book]: https://rust-lang.github.io/async-book/"] #[doc = " [`return`]: ../std/keyword.return.html"] #[doc = " [try operator]: ../reference/expressions/operator-expr.html#r-expr.try"] #[doc = " [never type]: ../reference/types/never.html"] #[doc = " [`Result`]: result::Result"] #[doc = " [async book blocks]: https://rust-lang.github.io/async-book/part-guide/more-async-await.html#async-blocks"] mod async_keyword { } #[doc (keyword = "await")] #[doc = " Suspend execution until the result of a [`Future`] is ready."] #[doc = ""] #[doc = " `.await`ing a future will suspend the current function's execution until the executor"] #[doc = " has run the future to completion."] #[doc = ""] #[doc = " Read the [async book] for details on how [`async`]/`await` and executors work."] #[doc = ""] #[doc = " ## Editions"] #[doc = ""] #[doc = " `await` is a keyword from the 2018 edition onwards."] #[doc = ""] #[doc = " It is available for use in stable Rust from version 1.39 onwards."] #[doc = ""] #[doc = " [`Future`]: future::Future"] #[doc = " [async book]: https://rust-lang.github.io/async-book/"] #[doc = " [`async`]: ../std/keyword.async.html"] mod await_keyword { } #[doc (keyword = "dyn")] #[doc = " `dyn` is a prefix of a [trait object]'s type."] #[doc = ""] #[doc = " The `dyn` keyword is used to highlight that calls to methods on the associated `Trait`"] #[doc = " are [dynamically dispatched]. To use the trait this way, it must be *dyn compatible*[^1]."] #[doc = ""] #[doc = " Unlike generic parameters or `impl Trait`, the compiler does not know the concrete type that"] #[doc = " is being passed. That is, the type has been [erased]."] #[doc = " As such, a `dyn Trait` reference contains _two_ pointers."] #[doc = " One pointer goes to the data (e.g., an instance of a struct)."] #[doc = " Another pointer goes to a map of method call names to function pointers"] #[doc = " (known as a virtual method table or vtable)."] #[doc = ""] #[doc = " At run-time, when a method needs to be called on the `dyn Trait`, the vtable is consulted to get"] #[doc = " the function pointer and then that function pointer is called."] #[doc = ""] #[doc = " See the Reference for more information on [trait objects][ref-trait-obj]"] #[doc = " and [dyn compatibility][ref-dyn-compat]."] #[doc = ""] #[doc = " ## Trade-offs"] #[doc = ""] #[doc = " The above indirection is the additional runtime cost of calling a function on a `dyn Trait`."] #[doc = " Methods called by dynamic dispatch generally cannot be inlined by the compiler."] #[doc = ""] #[doc = " However, `dyn Trait` is likely to produce smaller code than `impl Trait` / generic parameters as"] #[doc = " the method won't be duplicated for each concrete type."] #[doc = ""] #[doc = " [trait object]: ../book/ch17-02-trait-objects.html"] #[doc = " [dynamically dispatched]: https://en.wikipedia.org/wiki/Dynamic_dispatch"] #[doc = " [ref-trait-obj]: ../reference/types/trait-object.html"] #[doc = " [ref-dyn-compat]: ../reference/items/traits.html#dyn-compatibility"] #[doc = " [erased]: https://en.wikipedia.org/wiki/Type_erasure"] #[doc = " [^1]: Formerly known as *object safe*."] mod dyn_keyword { } #[doc (keyword = "union")] #[doc = " The [Rust equivalent of a C-style union][union]."] #[doc = ""] #[doc = " A `union` looks like a [`struct`] in terms of declaration, but all of its"] #[doc = " fields exist in the same memory, superimposed over one another. For instance,"] #[doc = " if we wanted some bits in memory that we sometimes interpret as a `u32` and"] #[doc = " sometimes as an `f32`, we could write:"] #[doc = ""] #[doc = " ```rust"] #[doc = " union IntOrFloat {"] #[doc = "     i: u32,"] #[doc = "     f: f32,"] #[doc = " }"] #[doc = ""] #[doc = " let mut u = IntOrFloat { f: 1.0 };"] #[doc = " // Reading the fields of a union is always unsafe"] #[doc = " assert_eq!(unsafe { u.i }, 1065353216);"] #[doc = " // Updating through any of the field will modify all of them"] #[doc = " u.i = 1073741824;"] #[doc = " assert_eq!(unsafe { u.f }, 2.0);"] #[doc = " ```"] #[doc = ""] #[doc = " # Matching on unions"] #[doc = ""] #[doc = " It is possible to use pattern matching on `union`s. A single field name must"] #[doc = " be used and it must match the name of one of the `union`'s field."] #[doc = " Like reading from a `union`, pattern matching on a `union` requires `unsafe`."] #[doc = ""] #[doc = " ```rust"] #[doc = " union IntOrFloat {"] #[doc = "     i: u32,"] #[doc = "     f: f32,"] #[doc = " }"] #[doc = ""] #[doc = " let u = IntOrFloat { f: 1.0 };"] #[doc = ""] #[doc = " unsafe {"] #[doc = "     match u {"] #[doc = "         IntOrFloat { i: 10 } => println!(\"Found exactly ten!\"),"] #[doc = "         // Matching the field `f` provides an `f32`."] #[doc = "         IntOrFloat { f } => println!(\"Found f = {f} !\"),"] #[doc = "     }"] #[doc = " }"] #[doc = " ```"] #[doc = ""] #[doc = " # References to union fields"] #[doc = ""] #[doc = " All fields in a `union` are all at the same place in memory which means"] #[doc = " borrowing one borrows the entire `union`, for the same lifetime:"] #[doc = ""] #[doc = " ```rust,compile_fail,E0502"] #[doc = " union IntOrFloat {"] #[doc = "     i: u32,"] #[doc = "     f: f32,"] #[doc = " }"] #[doc = ""] #[doc = " let mut u = IntOrFloat { f: 1.0 };"] #[doc = ""] #[doc = " let f = unsafe { &u.f };"] #[doc = " // This will not compile because the field has already been borrowed, even"] #[doc = " // if only immutably"] #[doc = " let i = unsafe { &mut u.i };"] #[doc = ""] #[doc = " *i = 10;"] #[doc = " println!(\"f = {f} and i = {i}\");"] #[doc = " ```"] #[doc = ""] #[doc = " See the [Reference][union] for more information on `union`s."] #[doc = ""] #[doc = " [`struct`]: keyword.struct.html"] #[doc = " [union]: ../reference/items/unions.html"] mod union_keyword { }